def get_credentials(var_value, fallback_user, fallback_pass):
    import sqlite3, os
    db_path = "Config/dbo_bitpack.db"
    if not os.path.exists(db_path):
        return fallback_user, fallback_pass
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("SELECT username, password FROM accounts WHERE var_value=?", (str(var_value),))
    result = cursor.fetchone()
    conn.close()
    return (result[0], result[1]) if result else (fallback_user, fallback_pass)
