def data_folder_creation_script():
    import os
    import base64
    from pathlib import Path

    def generate_recreation_script(source_folder='data', output_script='recreate_data.py'):    
        if not os.path.exists(source_folder):
            print("The data folder does not exist.")
            return
        
        # Exclude __pycache__ și alte foldere nedorite
        exclude_dirs = {'__pycache__', '.git', '.vscode', '__MACOSX'}
        
        # Colectează toate fișierele și datele lor
        files_data = []
        total_size = 0
        
        for root, dirs, files in os.walk(source_folder):
            # Exclude directoarele nedorite
            dirs[:] = [d for d in dirs if d not in exclude_dirs]
            
            relative_path = os.path.relpath(root, source_folder)
            
            for file in files:
                source_file = os.path.join(root, file)
                
                # Calculează calea relativă
                if relative_path != '.':
                    rel_file_path = os.path.join(relative_path, file).replace('\\', '/')
                else:
                    rel_file_path = file
                
                # Citește datele binare
                with open(source_file, 'rb') as f:
                    binary_data = f.read()
                
                if file.endswith('.pyc') or file.endswith('.pyo'):
                    continue
                
                # Convertește în base64 pentru a fi scris în script
                base64_data = base64.b64encode(binary_data).decode('utf-8')
                
                files_data.append({
                    'path': rel_file_path,
                    'data': base64_data,
                    'size': len(binary_data)
                })
                
                total_size += len(binary_data)
                print(f"  Processed: {rel_file_path} ({len(binary_data) / 1024:.2f} KB)")
        
        # Generează scriptul Python    
        with open(output_script, 'w', encoding='utf-8') as f:
            # Header
            f.write('#!/usr/bin/env python3\n')
            f.write('# -*- coding: utf-8 -*-\n')
            f.write('"""\n')
            f.write('Automatically generated script for recreating the `data` folder.\n')
            f.write(f'Total size: {total_size / (1024*1024):.2f} MB\n')
            f.write('"""\n\n')
            
            # Imports
            f.write('import os\n')
            f.write('import base64\n')
            f.write('from pathlib import Path\n\n')
            
            # Date binare - FIXAT: concatenare automată
            f.write('# Binary data (encoded in base64)\n')
            f.write('FILES_DATA = {\n')
            
            for file_info in files_data:
                path = file_info["path"]
                data = file_info["data"]
                
                # Împarte șirul în linii de max 2500 caractere
                f.write(f'    {repr(path)}: (\n')
                
                chunk_size = 5000
                for i in range(0, len(data), chunk_size):
                    chunk = data[i:i+chunk_size]
                    f.write(f'        {repr(chunk)}\n')
                
                f.write('    ),\n')
            
            f.write('}\n\n')
            
            # Funcția de recreare - FIXAT: concatenare tuple-uri
            f.write('def recreate_data_folder(output_folder="data_recreated"):\n')
            f.write('    if os.path.exists(output_folder):\n')
            f.write('        import shutil\n')
            f.write('        shutil.rmtree(output_folder)\n')
            f.write('    \n')
            f.write('    os.makedirs(output_folder, exist_ok=True)\n')
            f.write('    \n')
            f.write('    total_files = 0\n')
            f.write('    total_size = 0\n')
            f.write('    \n')
            f.write('    for file_path, base64_data in FILES_DATA.items():\n')
            f.write('        full_path = os.path.join(output_folder, file_path)\n')
            f.write('        \n')
            f.write('        os.makedirs(os.path.dirname(full_path), exist_ok=True)\n')
            f.write('        \n')
            f.write('        if isinstance(base64_data, tuple):\n')
            f.write('            base64_data = "".join(base64_data)\n')
            f.write('        \n')
            f.write('        binary_data = base64.b64decode(base64_data)\n')
            f.write('        with open(full_path, "wb") as f:\n')
            f.write('            f.write(binary_data)\n')
            f.write('        \n')
            f.write('        total_files += 1\n')
            f.write('        total_size += len(binary_data)\n')
            f.write('\n')
            
            # Main
            f.write('if __name__ == "__main__":\n')
            f.write('    import sys\n')
            f.write('    \n')
            f.write('    output_name = sys.argv[1] if len(sys.argv) > 1 else "data_recreated"\n')
            f.write('    \n')
            f.write('    recreate_data_folder(output_name)\n')
            f.write('    print("\\nDONE!\\n")\n')
        
        print("For usage:")
        print(f"   python {output_script}")
        print(f"   python {output_script} custom_folder_name")

    if __name__ == "__main__":    
        generate_recreation_script(source_folder='data', output_script='recreate_data.py')

def spaceinvaders():
    #from pygame import *
    from pygame import (
        sprite, Surface, SRCALPHA, display, time, draw, event, key, font,
        mixer, init, transform, image, QUIT, KEYDOWN, KEYUP,
        K_LEFT, K_RIGHT, K_SPACE, K_ESCAPE
    )
    import sys
    from random import choice

    # Colors (R, G, B)
    WHITE = (255, 255, 255)
    GREEN = (78, 255, 87)
    YELLOW = (241, 255, 0)
    BLUE = (80, 255, 239)
    PURPLE = (203, 0, 255)
    RED = (237, 28, 36)
    BLACK = (0, 0, 0)

    SCREEN = display.set_mode((800, 600))

    BLOCKERS_POSITION = 450
    ENEMY_DEFAULT_POSITION = 65
    ENEMY_MOVE_DOWN = 35


    def draw_ship(surface, x, y, color=GREEN):
        """Draw player ship"""
        # Base triangle
        points = [(x + 23, y), (x + 10, y + 25), (x + 36, y + 25)]
        draw.polygon(surface, color, points)
        # Base rectangle
        draw.rect(surface, color, (x + 15, y + 20, 16, 5))


    def draw_enemy_type1(surface, x, y, frame, color=PURPLE):
        """Draw top row enemy (octopus style)"""
        if frame == 0:
            # Arms up
            draw.rect(surface, color, (x + 5, y, 8, 3))  # Left arm
            draw.rect(surface, color, (x + 27, y, 8, 3))  # Right arm
            draw.rect(surface, color, (x + 10, y + 3, 20, 15))  # Body
            draw.rect(surface, color, (x + 8, y + 18, 6, 8))  # Left leg
            draw.rect(surface, color, (x + 26, y + 18, 6, 8))  # Right leg
        else:
            # Arms down
            draw.rect(surface, color, (x + 10, y + 3, 20, 15))  # Body
            draw.rect(surface, color, (x + 5, y + 18, 8, 8))  # Left arm down
            draw.rect(surface, color, (x + 27, y + 18, 8, 8))  # Right arm down
            draw.rect(surface, color, (x + 14, y + 26, 4, 6))  # Left leg
            draw.rect(surface, color, (x + 22, y + 26, 4, 6))  # Right leg


    def draw_enemy_type2(surface, x, y, frame, color=BLUE):
        """Draw middle row enemy (crab style)"""
        if frame == 0:
            # Claws out
            draw.rect(surface, color, (x + 2, y + 5, 4, 8))  # Left claw
            draw.rect(surface, color, (x + 34, y + 5, 4, 8))  # Right claw
            draw.rect(surface, color, (x + 10, y, 20, 20))  # Body
            draw.rect(surface, color, (x + 6, y + 20, 8, 6))  # Left leg
            draw.rect(surface, color, (x + 26, y + 20, 8, 6))  # Right leg
        else:
            # Claws in
            draw.rect(surface, color, (x + 5, y + 8, 6, 6))  # Left claw
            draw.rect(surface, color, (x + 29, y + 8, 6, 6))  # Right claw
            draw.rect(surface, color, (x + 10, y, 20, 20))  # Body
            draw.rect(surface, color, (x + 10, y + 20, 6, 6))  # Left leg
            draw.rect(surface, color, (x + 24, y + 20, 6, 6))  # Right leg


    def draw_enemy_type3(surface, x, y, frame, color=GREEN):
        """Draw bottom row enemy (squid style)"""
        if frame == 0:
            draw.rect(surface, color, (x + 12, y, 16, 10))  # Head
            draw.rect(surface, color, (x + 8, y + 10, 24, 8))  # Body
            draw.rect(surface, color, (x + 4, y + 18, 6, 8))  # Leg 1
            draw.rect(surface, color, (x + 12, y + 18, 4, 10))  # Leg 2
            draw.rect(surface, color, (x + 24, y + 18, 4, 10))  # Leg 3
            draw.rect(surface, color, (x + 30, y + 18, 6, 8))  # Leg 4
        else:
            draw.rect(surface, color, (x + 12, y, 16, 10))  # Head
            draw.rect(surface, color, (x + 8, y + 10, 24, 8))  # Body
            draw.rect(surface, color, (x + 8, y + 18, 4, 10))  # Leg 1
            draw.rect(surface, color, (x + 16, y + 18, 4, 8))  # Leg 2
            draw.rect(surface, color, (x + 20, y + 18, 4, 8))  # Leg 3
            draw.rect(surface, color, (x + 28, y + 18, 4, 10))  # Leg 4


    def draw_mystery(surface, x, y, color=RED):
        """Draw mystery ship (UFO)"""
        draw.ellipse(surface, color, (x + 10, y + 5, 55, 15))  # Top dome
        draw.rect(surface, color, (x, y + 15, 75, 8))  # Body
        draw.circle(surface, color, (x + 15, y + 23), 4)  # Light 1
        draw.circle(surface, color, (x + 37, y + 23), 4)  # Light 2
        draw.circle(surface, color, (x + 60, y + 23), 4)  # Light 3


    def draw_explosion(surface, x, y, size=1):
        """Draw explosion effect"""
        colors = [RED, YELLOW, WHITE]
        for i, color in enumerate(colors):
            offset = i * 3
            draw.circle(surface, color, (x + 20, y + 18), int(15 * size) - offset)


    class Ship(sprite.Sprite):
        def __init__(self):
            sprite.Sprite.__init__(self)
            self.image = Surface((46, 30), SRCALPHA)
            draw_ship(self.image, 0, 0)
            self.rect = self.image.get_rect(topleft=(375, 540))
            self.speed = 5

        def update(self, keys, *args):
            if keys[K_LEFT] and self.rect.x > 10:
                self.rect.x -= self.speed
            if keys[K_RIGHT] and self.rect.x < 740:
                self.rect.x += self.speed
            self.image = Surface((46, 30), SRCALPHA)
            draw_ship(self.image, 0, 0)
            game.screen.blit(self.image, self.rect)


    class Bullet(sprite.Sprite):
        def __init__(self, xpos, ypos, direction, speed, bullet_type, side):
            sprite.Sprite.__init__(self)
            if bullet_type == 'laser':
                self.image = Surface((4, 12))
                self.image.fill(WHITE)
            else:  # enemy laser
                self.image = Surface((4, 12))
                self.image.fill(RED)
            self.rect = self.image.get_rect(topleft=(xpos, ypos))
            self.speed = speed
            self.direction = direction
            self.side = side

        def update(self, keys, *args):
            game.screen.blit(self.image, self.rect)
            self.rect.y += self.speed * self.direction
            if self.rect.y < 15 or self.rect.y > 600:
                self.kill()


    class Enemy(sprite.Sprite):
        def __init__(self, row, column):
            sprite.Sprite.__init__(self)
            self.row = row
            self.column = column
            self.index = 0
            self.image = Surface((40, 35), SRCALPHA)
            self.rect = self.image.get_rect()
            self.colors = {0: PURPLE, 1: BLUE, 2: BLUE, 3: GREEN, 4: GREEN}
            self.draw_functions = {
                0: draw_enemy_type1,
                1: draw_enemy_type2,
                2: draw_enemy_type2,
                3: draw_enemy_type3,
                4: draw_enemy_type3
            }

        def toggle_image(self):
            self.index = 1 - self.index

        def update(self, *args):
            self.image = Surface((40, 35), SRCALPHA)
            draw_func = self.draw_functions[self.row]
            color = self.colors[self.row]
            draw_func(self.image, 0, 0, self.index, color)
            game.screen.blit(self.image, self.rect)


    class EnemiesGroup(sprite.Group):
        def __init__(self, columns, rows):
            sprite.Group.__init__(self)
            self.enemies = [[None] * columns for _ in range(rows)]
            self.columns = columns
            self.rows = rows
            self.leftAddMove = 0
            self.rightAddMove = 0
            self.moveTime = 600
            self.direction = 1
            self.rightMoves = 30
            self.leftMoves = 30
            self.moveNumber = 15
            self.timer = time.get_ticks()
            self.bottom = game.enemyPosition + ((rows - 1) * 45) + 35
            self._aliveColumns = list(range(columns))
            self._leftAliveColumn = 0
            self._rightAliveColumn = columns - 1

        def update(self, current_time):
            if current_time - self.timer > self.moveTime:
                if self.direction == 1:
                    max_move = self.rightMoves + self.rightAddMove
                else:
                    max_move = self.leftMoves + self.leftAddMove

                if self.moveNumber >= max_move:
                    self.leftMoves = 30 + self.rightAddMove
                    self.rightMoves = 30 + self.leftAddMove
                    self.direction *= -1
                    self.moveNumber = 0
                    self.bottom = 0
                    for enemy in self:
                        enemy.rect.y += ENEMY_MOVE_DOWN
                        enemy.toggle_image()
                        if self.bottom < enemy.rect.y + 35:
                            self.bottom = enemy.rect.y + 35
                else:
                    velocity = 10 if self.direction == 1 else -10
                    for enemy in self:
                        enemy.rect.x += velocity
                        enemy.toggle_image()
                    self.moveNumber += 1

                self.timer += self.moveTime

        def add_internal(self, *sprites):
            super(EnemiesGroup, self).add_internal(*sprites)
            for s in sprites:
                self.enemies[s.row][s.column] = s

        def remove_internal(self, *sprites):
            super(EnemiesGroup, self).remove_internal(*sprites)
            for s in sprites:
                self.kill(s)
            self.update_speed()

        def is_column_dead(self, column):
            return not any(self.enemies[row][column]
                           for row in range(self.rows))

        def random_bottom(self):
            col = choice(self._aliveColumns)
            col_enemies = (self.enemies[row - 1][col]
                           for row in range(self.rows, 0, -1))
            return next((en for en in col_enemies if en is not None), None)

        def update_speed(self):
            if len(self) == 1:
                self.moveTime = 200
            elif len(self) <= 10:
                self.moveTime = 400

        def kill(self, enemy):
            self.enemies[enemy.row][enemy.column] = None
            is_column_dead = self.is_column_dead(enemy.column)
            if is_column_dead:
                self._aliveColumns.remove(enemy.column)

            if enemy.column == self._rightAliveColumn:
                while self._rightAliveColumn > 0 and is_column_dead:
                    self._rightAliveColumn -= 1
                    self.rightAddMove += 5
                    is_column_dead = self.is_column_dead(self._rightAliveColumn)

            elif enemy.column == self._leftAliveColumn:
                while self._leftAliveColumn < self.columns and is_column_dead:
                    self._leftAliveColumn += 1
                    self.leftAddMove += 5
                    is_column_dead = self.is_column_dead(self._leftAliveColumn)


    class Blocker(sprite.Sprite):
        def __init__(self, size, color, row, column):
            sprite.Sprite.__init__(self)
            self.height = size
            self.width = size
            self.color = color
            self.image = Surface((self.width, self.height))
            self.image.fill(self.color)
            self.rect = self.image.get_rect()
            self.row = row
            self.column = column

        def update(self, keys, *args):
            game.screen.blit(self.image, self.rect)


    class Mystery(sprite.Sprite):
        def __init__(self):
            sprite.Sprite.__init__(self)
            self.image = Surface((75, 35), SRCALPHA)
            draw_mystery(self.image, 0, 0)
            self.rect = self.image.get_rect(topleft=(-80, 45))
            self.row = 5
            self.moveTime = 25000
            self.direction = 1
            self.timer = time.get_ticks()

        def update(self, keys, currentTime, *args):
            resetTimer = False
            passed = currentTime - self.timer
            if passed > self.moveTime:
                if self.rect.x < 840 and self.direction == 1:
                    self.rect.x += 2
                    self.image = Surface((75, 35), SRCALPHA)
                    draw_mystery(self.image, 0, 0)
                    game.screen.blit(self.image, self.rect)
                if self.rect.x > -100 and self.direction == -1:
                    self.rect.x -= 2
                    self.image = Surface((75, 35), SRCALPHA)
                    draw_mystery(self.image, 0, 0)
                    game.screen.blit(self.image, self.rect)

            if self.rect.x > 830:
                self.direction = -1
                resetTimer = True
            if self.rect.x < -90:
                self.direction = 1
                resetTimer = True
            if passed > self.moveTime and resetTimer:
                self.timer = currentTime


    class EnemyExplosion(sprite.Sprite):
        def __init__(self, enemy, *groups):
            super(EnemyExplosion, self).__init__(*groups)
            self.image = Surface((50, 45), SRCALPHA)
            self.rect = self.image.get_rect(topleft=(enemy.rect.x, enemy.rect.y))
            self.timer = time.get_ticks()

        def update(self, current_time, *args):
            passed = current_time - self.timer
            if passed <= 100:
                self.image = Surface((40, 35), SRCALPHA)
                draw_explosion(self.image, 0, 0, 0.8)
                game.screen.blit(self.image, self.rect)
            elif passed <= 200:
                self.image = Surface((50, 45), SRCALPHA)
                draw_explosion(self.image, -5, -5, 1.2)
                game.screen.blit(self.image, (self.rect.x - 6, self.rect.y - 6))
            elif 400 < passed:
                self.kill()


    class MysteryExplosion(sprite.Sprite):
        def __init__(self, mystery, score, *groups):
            super(MysteryExplosion, self).__init__(*groups)
            self.text = Text(None, 20, str(score), WHITE,
                             mystery.rect.x + 20, mystery.rect.y + 6)
            self.timer = time.get_ticks()

        def update(self, current_time, *args):
            passed = current_time - self.timer
            if passed <= 200 or 400 < passed <= 600:
                self.text.draw(game.screen)
            elif 600 < passed:
                self.kill()


    class ShipExplosion(sprite.Sprite):
        def __init__(self, ship, *groups):
            super(ShipExplosion, self).__init__(*groups)
            self.image = Surface((46, 30), SRCALPHA)
            draw_ship(self.image, 0, 0, RED)
            self.rect = self.image.get_rect(topleft=(ship.rect.x, ship.rect.y))
            self.timer = time.get_ticks()

        def update(self, current_time, *args):
            passed = current_time - self.timer
            if 300 < passed <= 600:
                game.screen.blit(self.image, self.rect)
            elif 900 < passed:
                self.kill()


    class Life(sprite.Sprite):
        def __init__(self, xpos, ypos):
            sprite.Sprite.__init__(self)
            self.image = Surface((23, 23), SRCALPHA)
            draw_ship(self.image, -10, -5, GREEN)
            self.rect = self.image.get_rect(topleft=(xpos, ypos))

        def update(self, *args):
            game.screen.blit(self.image, self.rect)


    class Text(object):
        def __init__(self, textFont, size, message, color, xpos, ypos):
            self.font = font.Font(textFont, size)
            self.surface = self.font.render(message, True, color)
            self.rect = self.surface.get_rect(topleft=(xpos, ypos))

        def draw(self, surface):
            surface.blit(self.surface, self.rect)


    class SpaceInvaders(object):
        def __init__(self):
            mixer.pre_init(44100, -16, 1, 4096)
            init()
            self.clock = time.Clock()
            self.caption = display.set_caption('Space Invaders')
            self.screen = SCREEN
            self.background = Surface((800, 600))
            self.background.fill(BLACK)
            self.startGame = False
            self.mainScreen = True
            self.gameOver = False
            self.enemyPosition = ENEMY_DEFAULT_POSITION
            self.titleText = Text(None, 50, 'Space Invaders', WHITE, 164, 155)
            self.titleText2 = Text(None, 25, 'Press any key to continue', WHITE,
                                   201, 225)
            self.gameOverText = Text(None, 50, 'Game Over', WHITE, 250, 270)
            self.nextRoundText = Text(None, 50, 'Next Round', WHITE, 240, 270)
            self.enemy1Text = Text(None, 25, '   =   10 pts', GREEN, 368, 270)
            self.enemy2Text = Text(None, 25, '   =  20 pts', BLUE, 368, 320)
            self.enemy3Text = Text(None, 25, '   =  30 pts', PURPLE, 368, 370)
            self.enemy4Text = Text(None, 25, '   =  ?????', RED, 368, 420)
            self.scoreText = Text(None, 20, 'Score', WHITE, 5, 5)
            self.livesText = Text(None, 20, 'Lives ', WHITE, 640, 5)

            self.life1 = Life(715, 3)
            self.life2 = Life(742, 3)
            self.life3 = Life(769, 3)
            self.livesGroup = sprite.Group(self.life1, self.life2, self.life3)

        def reset(self, score):
            self.player = Ship()
            self.playerGroup = sprite.Group(self.player)
            self.explosionsGroup = sprite.Group()
            self.bullets = sprite.Group()
            self.mysteryShip = Mystery()
            self.mysteryGroup = sprite.Group(self.mysteryShip)
            self.enemyBullets = sprite.Group()
            self.make_enemies()
            self.allSprites = sprite.Group(self.player, self.enemies,
                                           self.livesGroup, self.mysteryShip)
            self.keys = key.get_pressed()

            self.timer = time.get_ticks()
            self.noteTimer = time.get_ticks()
            self.shipTimer = time.get_ticks()
            self.score = score
            self.makeNewShip = False
            self.shipAlive = True

        def make_blockers(self, number):
            blockerGroup = sprite.Group()
            for row in range(4):
                for column in range(9):
                    blocker = Blocker(10, GREEN, row, column)
                    blocker.rect.x = 50 + (200 * number) + (column * blocker.width)
                    blocker.rect.y = BLOCKERS_POSITION + (row * blocker.height)
                    blockerGroup.add(blocker)
            return blockerGroup

        @staticmethod
        def should_exit(evt):
            return evt.type == QUIT or (evt.type == KEYUP and evt.key == K_ESCAPE)

        def check_input(self):
            self.keys = key.get_pressed()
            for e in event.get():
                if self.should_exit(e):
                    sys.exit()
                if e.type == KEYDOWN:
                    if e.key == K_SPACE:
                        if len(self.bullets) == 0 and self.shipAlive:
                            if self.score < 1000:
                                bullet = Bullet(self.player.rect.x + 23,
                                                self.player.rect.y + 5, -1,
                                                15, 'laser', 'center')
                                self.bullets.add(bullet)
                                self.allSprites.add(self.bullets)
                            else:
                                leftbullet = Bullet(self.player.rect.x + 8,
                                                    self.player.rect.y + 5, -1,
                                                    15, 'laser', 'left')
                                rightbullet = Bullet(self.player.rect.x + 38,
                                                     self.player.rect.y + 5, -1,
                                                     15, 'laser', 'right')
                                self.bullets.add(leftbullet)
                                self.bullets.add(rightbullet)
                                self.allSprites.add(self.bullets)

        def make_enemies(self):
            enemies = EnemiesGroup(10, 5)
            for row in range(5):
                for column in range(10):
                    enemy = Enemy(row, column)
                    enemy.rect.x = 157 + (column * 50)
                    enemy.rect.y = self.enemyPosition + (row * 45)
                    enemies.add(enemy)

            self.enemies = enemies

        def make_enemies_shoot(self):
            if (time.get_ticks() - self.timer) > 700 and self.enemies:
                enemy = self.enemies.random_bottom()
                self.enemyBullets.add(
                    Bullet(enemy.rect.x + 14, enemy.rect.y + 20, 1, 5,
                           'enemylaser', 'center'))
                self.allSprites.add(self.enemyBullets)
                self.timer = time.get_ticks()

        def calculate_score(self, row):
            scores = {0: 30, 1: 20, 2: 20, 3: 10, 4: 10,
                      5: choice([50, 100, 150, 300])}
            score = scores[row]
            self.score += score
            return score

        def create_main_menu(self):
            enemy1_surf = Surface((40, 35), SRCALPHA)
            draw_enemy_type1(enemy1_surf, 0, 0, 0, PURPLE)
            self.screen.blit(enemy1_surf, (318, 270))
            
            enemy2_surf = Surface((40, 35), SRCALPHA)
            draw_enemy_type2(enemy2_surf, 0, 0, 0, BLUE)
            self.screen.blit(enemy2_surf, (318, 320))
            
            enemy3_surf = Surface((40, 35), SRCALPHA)
            draw_enemy_type3(enemy3_surf, 0, 0, 0, GREEN)
            self.screen.blit(enemy3_surf, (318, 370))
            
            enemy4_surf = Surface((75, 35), SRCALPHA)
            draw_mystery(enemy4_surf, 0, 0, RED)
            self.screen.blit(enemy4_surf, (299, 420))

        def check_collisions(self):
            sprite.groupcollide(self.bullets, self.enemyBullets, True, True)

            for enemy in sprite.groupcollide(self.enemies, self.bullets,
                                             True, True).keys():
                self.calculate_score(enemy.row)
                EnemyExplosion(enemy, self.explosionsGroup)
                self.gameTimer = time.get_ticks()

            for mystery in sprite.groupcollide(self.mysteryGroup, self.bullets,
                                               True, True).keys():
                score = self.calculate_score(mystery.row)
                MysteryExplosion(mystery, score, self.explosionsGroup)
                newShip = Mystery()
                self.allSprites.add(newShip)
                self.mysteryGroup.add(newShip)

            for player in sprite.groupcollide(self.playerGroup, self.enemyBullets,
                                              True, True).keys():
                if self.life3.alive():
                    self.life3.kill()
                elif self.life2.alive():
                    self.life2.kill()
                elif self.life1.alive():
                    self.life1.kill()
                else:
                    self.gameOver = True
                    self.startGame = False
                ShipExplosion(player, self.explosionsGroup)
                self.makeNewShip = True
                self.shipTimer = time.get_ticks()
                self.shipAlive = False

            if self.enemies.bottom >= 540:
                sprite.groupcollide(self.enemies, self.playerGroup, True, True)
                if not self.player.alive() or self.enemies.bottom >= 600:
                    self.gameOver = True
                    self.startGame = False

            sprite.groupcollide(self.bullets, self.allBlockers, True, True)
            sprite.groupcollide(self.enemyBullets, self.allBlockers, True, True)
            if self.enemies.bottom >= BLOCKERS_POSITION:
                sprite.groupcollide(self.enemies, self.allBlockers, False, True)

        def create_new_ship(self, createShip, currentTime):
            if createShip and (currentTime - self.shipTimer > 900):
                self.player = Ship()
                self.allSprites.add(self.player)
                self.playerGroup.add(self.player)
                self.makeNewShip = False
                self.shipAlive = True

        def create_game_over(self, currentTime):
            self.screen.blit(self.background, (0, 0))
            passed = currentTime - self.timer
            if passed < 750:
                self.gameOverText.draw(self.screen)
            elif 750 < passed < 1500:
                self.screen.blit(self.background, (0, 0))
            elif 1500 < passed < 2250:
                self.gameOverText.draw(self.screen)
            elif 2250 < passed < 2750:
                self.screen.blit(self.background, (0, 0))
            elif passed > 3000:
                self.mainScreen = True

            for e in event.get():
                if self.should_exit(e):
                    sys.exit()

        def main(self):
            while True:
                if self.mainScreen:
                    self.screen.blit(self.background, (0, 0))
                    self.titleText.draw(self.screen)
                    self.titleText2.draw(self.screen)
                    self.enemy1Text.draw(self.screen)
                    self.enemy2Text.draw(self.screen)
                    self.enemy3Text.draw(self.screen)
                    self.enemy4Text.draw(self.screen)
                    self.create_main_menu()
                    for e in event.get():
                        if self.should_exit(e):
                            sys.exit()
                        if e.type == KEYUP:
                            self.allBlockers = sprite.Group(self.make_blockers(0),
                                                            self.make_blockers(1),
                                                            self.make_blockers(2),
                                                            self.make_blockers(3))
                            self.livesGroup.add(self.life1, self.life2, self.life3)
                            self.reset(0)
                            self.startGame = True
                            self.mainScreen = False

                elif self.startGame:
                    if not self.enemies and not self.explosionsGroup:
                        currentTime = time.get_ticks()
                        if currentTime - self.gameTimer < 3000:
                            self.screen.blit(self.background, (0, 0))
                            self.scoreText2 = Text(None, 20, str(self.score),
                                                   GREEN, 85, 5)
                            self.scoreText.draw(self.screen)
                            self.scoreText2.draw(self.screen)
                            self.nextRoundText.draw(self.screen)
                            self.livesText.draw(self.screen)
                            self.livesGroup.update()
                            self.check_input()
                        if currentTime - self.gameTimer > 3000:
                            self.enemyPosition += ENEMY_MOVE_DOWN
                            self.reset(self.score)
                            self.gameTimer += 3000
                    else:
                        currentTime = time.get_ticks()
                        self.screen.blit(self.background, (0, 0))
                        self.allBlockers.update(self.screen)
                        self.scoreText2 = Text(None, 20, str(self.score), GREEN,
                                               85, 5)
                        self.scoreText.draw(self.screen)
                        self.scoreText2.draw(self.screen)
                        self.livesText.draw(self.screen)
                        self.check_input()
                        self.enemies.update(currentTime)
                        self.allSprites.update(self.keys, currentTime)
                        self.explosionsGroup.update(currentTime)
                        self.check_collisions()
                        self.create_new_ship(self.makeNewShip, currentTime)
                        self.make_enemies_shoot()

                elif self.gameOver:
                    currentTime = time.get_ticks()
                    # Reset enemy starting position
                    self.enemyPosition = ENEMY_DEFAULT_POSITION
                    self.create_game_over(currentTime)

                display.update()
                self.clock.tick(60)


    if __name__ == '__main__':
        game = SpaceInvaders()
        game.main()

def ludogame():
    #from tkinter import *
    from tkinter import messagebox
    import time
    from random import randint, choice

    class Ludo:
        def __init__(self, rootludo,six_side_block,five_side_block,four_side_block,three_side_block,two_side_block,one_side_block):
            self.window = rootludo
            # Make canvas
            self.make_canvas = Canvas(self.window, bg="#141414", width=800, height=630)
            self.make_canvas.pack(fill=BOTH,expand=1)

            # Make some containers to store data
            self.made_red_coin = []
            self.made_green_coin = []
            self.made_yellow_coin = []
            self.made_sky_blue_coin = []

            self.red_number_label = []
            self.green_number_label = []
            self.yellow_number_label = []
            self.sky_blue_number_label = []

            self.block_value_predict = []
            self.total_people_play = []

            # Ludo block all side image store
            self.block_number_side = [self.draw_dice(self.make_canvas, i) for i in range(1, 7)]

            # Use for store specific position of all coins
            self.red_coord_store = [-1, -1, -1, -1]
            self.green_coord_store = [-1, -1, -1, -1]
            self.yellow_coord_store = [-1, -1, -1, -1]
            self.sky_blue_coord_store = [-1, -1, -1, -1]

