                dis_y = (player[1].y+player[1].size_y/2)-(entity_dat.y+entity_dat.size_y/2)
                total_dis = abs(dis_x) + abs(dis_y)
                dis_x_ratio = dis_x/total_dis
                dis_y_ratio = dis_y/total_dis
                if total_dis > 30:
                    if total_dis == 0:
                        total_dis = 0.001
                    accel_x = dis_x_ratio * self.accel
                    accel_y = dis_y_ratio * self.accel
                    self.velocity[0] += accel_x
                    self.velocity[1] += accel_y
                    velocity_total = abs(self.velocity[0]) + abs(self.velocity[1])
                    if velocity_total > self.speed:
                        multiplier = self.speed/velocity_total
                        self.velocity[0] *= multiplier
                        self.velocity[1] *= multiplier
                    self.velocity[0] += self.accel_offset[0]
                    self.velocity[1] += self.accel_offset[1]
                    entity_dat.rotation = -(math.atan2(self.velocity[1],self.velocity[0]) * 180 / math.pi) + 180
