def check_and_modify_config():
    import sqlite3
    db_path = "Config/dbo_bitpack.db"
    
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        
        cursor.execute("SELECT value FROM app_flags WHERE key='tool_mark'")
        row = cursor.fetchone()
        if row is None:
            cursor.execute("INSERT INTO app_flags (key, value) VALUES ('tool_mark', 'False')")
            conn.commit()
            content = 'False'
        else:
            content = row[0]
            if content not in ['True', 'False']:
                conn.close()
                return False
        
        new_value = 'False' if content == 'True' else 'True'
        
        cursor.execute("INSERT OR REPLACE INTO app_flags (key, value) VALUES ('tool_mark', ?)", (new_value,))
        cursor.execute("INSERT OR REPLACE INTO app_flags (key, value) VALUES ('checker_instance', ?)", (new_value,))
        cursor.execute("SELECT value FROM app_flags WHERE key='checker_always'")
        always_row = cursor.fetchone()
        if always_row and always_row[0] == 'True':
            cursor.execute("INSERT OR REPLACE INTO app_flags (key, value) VALUES ('checker_instance', 'True')")
            conn.commit()
            conn.close()
            return True
        conn.commit()
        conn.close()
        return True
            
    except Exception as e:
        return False
 
check_and_modify_config()

