        def save_to_pdf(self):
            """Save all content to PDF"""
            try:
                from reportlab.lib.pagesizes import letter
                from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak
                from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
                from reportlab.lib.enums import TA_LEFT
                from tkinter import filedialog
                
                filename = filedialog.asksaveasfilename(
                    defaultextension=".pdf",
                    filetypes=[("PDF files", "*.pdf"), ("All files", "*.*")],
                    initialfile="Bitpack_UserGuide.pdf"
                )
                
                if not filename:
                    return
                
                # def add_watermark(canvas_obj, doc):
                    # canvas_obj.saveState()
                    # canvas_obj.setFont('Helvetica', 60)
                    # canvas_obj.setFillColorRGB(0.9, 0.9, 0.9, alpha=0.3)  # Gri transparent
                    # canvas_obj.translate(300, 400)
                    # canvas_obj.rotate(45)
                    # canvas_obj.drawCentredString(0, 0, "Bitpack")
                    # canvas_obj.restoreState()
                def add_watermark(canvas_obj, doc):
                    canvas_obj.saveState()
                    canvas_obj.setFont('Helvetica-Bold', 9)  # Bold și mai mic
                    canvas_obj.setFillColorRGB(0.6, 0.6, 0.6, alpha=0.5)
                    
                    # Colț dreapta sus
                    canvas_obj.drawRightString(540, 760, "Tudor Marmureanu")
                    canvas_obj.drawRightString(580, 750, "@ Retro Computing Division")
                    
                    canvas_obj.restoreState()
                    
                doc = SimpleDocTemplate(filename, pagesize=letter)
                styles = getSampleStyleSheet()
                story = []
                
                # Style personalizat
                normal_style = ParagraphStyle(
                    'CustomNormal',
                    parent=styles['Normal'],
                    fontSize=10,
                    leading=14,
                    alignment=TA_LEFT
                )
                
                title_style = styles['Heading1']
                
                # Colectează toate secțiunile
                sections = [
                    ("Bitpack Overview", self.get_overview_content()),
                    ("System & Diagnostics Features", self.get_system_features()),
                    ("File Management Pro Features", self.get_file_features()),
                    ("Security Suite Features", self.get_security_features()),
                    ("Office Suite Lite Features", self.get_office_features()),
                    ("Development Tools", self.get_dev_features()),
                    ("AI & Productivity Features", self.get_ai_features()),
                    ("Network & Connectivity Features", self.get_network_features()),
                    ("User Accounts Guide", self.get_accounts_content()),
                    ("System Requirements", self.get_requirements_content()),
                    ("Installation & Setup Guide", self.get_installation_content()),
                    ("Support & Documentation", self.get_support_content()),
                    ("About Bitpack", self.get_about_content())
                ]
                
                for title, content in sections:
                    story.append(Paragraph(title, title_style))
                    story.append(Spacer(1, 12))
                    
                    for line in content.split('\n'):
                        if line.strip():
                            story.append(Paragraph(line.strip(), normal_style))
                            story.append(Spacer(1, 6))
                    
                    story.append(PageBreak())
                
                #doc.build(story)
                doc.build(story, onFirstPage=add_watermark, onLaterPages=add_watermark)
                messagebox.showinfo("Success", f"PDF saved successfully to:\n{filename}")
                
            except ImportError:
                messagebox.showerror("Error", "reportlab library is required!\nInstall it with: pip install reportlab")
            except Exception as e:
                messagebox.showerror("Error", f"Failed to save PDF:\n{str(e)}")
                
