def ch_inst_and_virt_inst_and_reading_db():    
    import sqlite3
    conn = sqlite3.connect("Config/dbo_bitpack.db")
    cursor = conn.cursor()

    for key in ['checker_instance', 'virtual_instance', 'reading_pane']:
        cursor.execute("SELECT value FROM app_flags WHERE key=?", (key,))
        if cursor.fetchone() is None:
            cursor.execute("INSERT INTO app_flags (key, value) VALUES (?, 'True')", (key,))

    conn.commit()

    cursor.execute("SELECT value FROM app_flags WHERE key='checker_instance'")
    row = cursor.fetchone()
    checker_instance = row[0] == 'True' if row else False

    cursor.execute("SELECT value FROM app_flags WHERE key='virtual_instance'")
    row = cursor.fetchone()
    virtual_instance = row[0] == 'True' if row else False

    cursor.execute("SELECT value FROM app_flags WHERE key='reading_pane'")
    row = cursor.fetchone()
    reading_pane = row[0] == 'True' if row else False

    conn.close()

    if reading_pane:
        run_reading_pane() 
