def handle_tool_mark():
    import sqlite3
    db_path = "Config/dbo_bitpack.db"
    
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute("INSERT OR REPLACE INTO app_flags (key, value) VALUES ('tool_mark', 'True')")
        conn.commit()
        conn.close()
        return 'True'
    except:
        return None
        
handle_tool_mark()

