def save_auto_login_data(username, password):
    import sqlite3
    conn = sqlite3.connect("Config/dbo_bitpack.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id FROM auto_login WHERE id=1")
    if cursor.fetchone():
        cursor.execute("UPDATE auto_login SET username=?, password=? WHERE id=1", (username, password))
    else:
        cursor.execute("INSERT INTO auto_login (id, username, password) VALUES (1, ?, ?)", (username, password))
    conn.commit()
    conn.close()

def load_auto_login_data():
    import sqlite3
    try:
        conn = sqlite3.connect("Config/dbo_bitpack.db")
        cursor = conn.cursor()
        cursor.execute("SELECT username, password FROM auto_login WHERE id=1")
        row = cursor.fetchone()
        conn.close()
        if row:
            return row[0], row[1]
    except Exception as e:
        print(f"Error loading auto-login: {e}")
    return None, None

def delete_auto_login_data():
    import sqlite3
    try:
        conn = sqlite3.connect("Config/dbo_bitpack.db")
        cursor = conn.cursor()
        cursor.execute("DELETE FROM auto_login WHERE id=1")
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"Error deleting auto-login: {e}")

def on_auto_login_check():
    """Function called when auto-login checkbox is checked/unchecked"""
    if auto_login_var.get():
        # Checkbox was checked - always show popup (with existing data pre-filled if available)
        show_auto_login_popup()
    # When unchecked - do nothing, just ignore the auto-login file

def open_current_folder_for_Multiapp():
    current_dir = os.getcwd()
    os.startfile(current_dir)

def show_auto_login_popup():
    """Shows popup for entering auto-login data"""
    popup = tk.Toplevel(windowlogin)
    popup.title("Auto-Login Setup")
    popup.geometry("400x300")
    popup.configure(bg='#333333')
    popup.resizable(False, False)
    popup.grab_set()  # Makes popup modal
    
    # Centers popup relative to main window
    popup.transient(windowlogin)
    
    frame = tk.Frame(popup, bg='gray20')
    frame.pack(expand=True, fill='both', padx=20, pady=20)
    
    # Label and field for username
    tk.Label(frame, text="Username for Auto-Login:", bg='gray20', fg="lime green", 
             font=("Fixedsys", 12, "bold")).grid(row=0, column=0, sticky="w", pady=5)
    
    popup_username = tk.Entry(frame, font=("Fixedsys", 12, "bold"), bg="gray40", 
                             fg="cyan", bd=5, insertbackground="lime green", width=30)
    popup_username.grid(row=1, column=0, pady=5)
    
    # Label and field for password
    tk.Label(frame, text="Password for Auto-Login:", bg='gray20', fg="lime green", 
             font=("Fixedsys", 12, "bold")).grid(row=2, column=0, sticky="w", pady=5)
    
    popup_password = tk.Entry(frame, show="*", font=("Fixedsys", 12, "bold"), bg="gray40", 
                             fg="cyan", bd=5, insertbackground="lime green", width=30)
    popup_password.grid(row=3, column=0, pady=5)
    
    # Load existing data if available and pre-fill the fields
    existing_username, existing_password = load_auto_login_data()
    if existing_username:
        popup_username.insert(0, existing_username)
        popup_password.insert(0, existing_password if existing_password else "")
    
    def save_and_close():
        username = popup_username.get().strip()
        password = popup_password.get().strip()
        
        if username:
            save_auto_login_data(username, password)
            # Automatically fill main form fields
            username_entry.delete(0, tk.END)
            username_entry.insert(0, username)
            password_entry.delete(0, tk.END)
            password_entry.insert(0, password)
            popup.destroy()
        else:
            messagebox.showerror("Error", "Username cannot be empty!")
    
    def cancel_and_close():
        # Uncheck checkbox if user cancels
        auto_login_var.set(False)
        popup.destroy()
    
    # Buttons
    button_frame = tk.Frame(frame, bg='gray20')
    button_frame.grid(row=4, column=0, pady=20)
    
    tk.Button(button_frame, text="OK", bg="black", fg="cyan", bd=5, 
              font=("Fixedsys", 12), command=save_and_close).pack(side=tk.LEFT, padx=5)
    
    tk.Button(button_frame, text="Cancel", bg="black", fg="red", bd=5, 
              font=("Fixedsys", 12), command=cancel_and_close).pack(side=tk.LEFT, padx=5)
    
    # Focus on first field
    popup_username.focus()
    popup.bind("<Return>", lambda event: save_and_close())

def load_auto_login_on_startup():
    """Loads auto-login data on application startup"""
    username, password = load_auto_login_data()
    if username:
        auto_login_var.set(True)
        username_entry.delete(0, tk.END)
        username_entry.insert(0, username)
        if password:
            password_entry.delete(0, tk.END)
            password_entry.insert(0, password)
            
