    def save_login_attempt(username, password):
        """
        Salvează orice încercare de logare în baza de date,
        indiferent dacă este reușită sau eșuată.
        """
        import sqlite3
        
        conn = sqlite3.connect("Config/dbo_bitpack.db")
        cursor = conn.cursor()
        
        # Caută dacă există cont corespunzător (verifică AMBELE variante)
        cursor.execute('''
            SELECT var_value, app_name FROM accounts 
            WHERE LOWER(username) = ? AND (password = ? OR (password = '' AND ? = ''))
        ''', (username.lower(), password, password))
        
        result = cursor.fetchone()
        
        if result:
            var_value = result[0]
            app_name = result[1]
            login_status = 'Success'
        else:
            var_value = None
            app_name = "Unknown/Invalid"
            login_status = 'Failed'
        
        # Salvează încercarea de logare (reușită SAU eșuată)
        cursor.execute('''
            INSERT INTO login_history (username, password, var_value, app_name, login_status)
            VALUES (?, ?, ?, ?, ?)
        ''', (username.lower(), password, var_value, app_name, login_status))
        
        conn.commit()
        conn.close()
    
