def create_w95_popup():
    # Creăm fereastra popup
    popup = tk.Toplevel()
    popup.title("")  # Fără titlu
    popup.overrideredirect(True)  # Elimină bara de titlu
    popup.geometry("400x150")
    popup.configure(bg='#000080')
    popup.resizable(False, False)
    
    # Poziționăm popup-ul în colțul din dreapta jos
    popup.update_idletasks()
    screen_width = popup.winfo_screenwidth()
    screen_height = popup.winfo_screenheight()
    x = screen_width - 420  # 400 + 20 pentru margine
    y = screen_height - 180  # 150 + 30 pentru margine
    popup.geometry(f"400x150+{x}+{y}")
    
    # Cadru principal cu efectul 3D tipic W95
    main_frame = tk.Frame(popup, bg='#c0c0c0', relief='raised', bd=2)
    main_frame.pack(fill='both', expand=True, padx=2, pady=2)
    
    # Bara de titlu falsă cu albastrul tipic W95
    title_frame = tk.Frame(main_frame, bg='#000080', height=20)
    title_frame.pack(fill='x', pady=(2, 0))
    title_frame.pack_propagate(False)
    
    # Butonul X pentru închidere
    close_button = tk.Button(
        title_frame, 
        text='×', 
        bg='#c0c0c0', 
        fg='black',
        font=('MS Sans Serif', 12, 'bold'),
        bd=1,
        width=2,
        height=1,
        relief='raised',
        command=popup.destroy
    )
    close_button.pack(side='right', padx=2, pady=1)
    
    # Cadru pentru conținut
    content_frame = tk.Frame(main_frame, bg='#c0c0c0')
    content_frame.pack(fill='both', expand=True, padx=10, pady=10)
    
    # Iconița de informație (opțional, stil W95)
    icon_label = tk.Label(
        content_frame, 
        text='ⓘ', 
        bg='#c0c0c0', 
        fg='#000080',
        font=('MS Sans Serif', 24, 'bold')
    )
    icon_label.pack(side='left', padx=(0, 10), anchor='n')
    
    # Textul principal
    message_label = tk.Label(
        content_frame,
        text="Try extension/manager, w95dist, devcpp, config/editor or RFLAGS.\nUse User Accounts tab from User Guide or type launcher/launcher",
        bg='#c0c0c0',
        fg='black',
        font=('MS Sans Serif', 9),
        justify='left',
        wraplength=300
    )
    message_label.pack(side='left', anchor='n', pady=10)
    
    # NU facem popup-ul modal pentru a nu bloca input-urile
    popup.transient(windowlogin)  # Se referă la fereastra principală
    # popup.grab_set()  # Comentat pentru a nu bloca input-urile
    
    # Efecte hover pentru butonul X
    def on_enter(e):
        close_button.config(relief='sunken')
    
    def on_leave(e):
        close_button.config(relief='raised')
    
    close_button.bind('<Enter>', on_enter)
    close_button.bind('<Leave>', on_leave)

