def check_01():
    import sqlite3
    db_path = "Config/dbo_bitpack.db"
    
    if not os.path.exists("Config"):
        try:
            os.makedirs("Config")
        except:
            return True
    
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute("SELECT value FROM app_flags WHERE key='mark01'")
        row = cursor.fetchone()
        
        if row and row[0] == "True":
            conn.close()
            return False  # Nu afisa popup
        
        # Nu exista sau nu e "True" - seteaza True si afiseaza popup
        cursor.execute("INSERT OR REPLACE INTO app_flags (key, value) VALUES ('mark01', 'True')")
        conn.commit()
        conn.close()
        return True
    except:
        return True

