            tk.Label(desc_inner, text="Description:", font=('MS Sans Serif', 9, 'bold'),
                    bg=self.bg_color, fg=self.text_color).pack(anchor=tk.W)
            self.desc_text = tk.Text(desc_inner, height=3, font=('MS Sans Serif', 9),
                                    relief=tk.SUNKEN, bd=2)
