    class SetupWizard(tk.Tk):
        def __init__(self):
            super().__init__()
     
            self.title("Repair Setup - Fetcher")
            self.geometry("500x400")
            self.resizable(False, False)
     
            self.steps = []
            self.current_step = 0
     
            self.container = ttk.Frame(self)
            self.container.pack(fill="both", expand=True)
     
            self.create_steps()
            self.show_step(0)
     
