        def setup_styles(self):
            style = ttk.Style()
            
            # Stil butoane
            style.configure(
                "TButton",
                background=self.colors["bg_input"],
                foreground=self.colors["text_primary"],
                borderwidth=0,
                relief=tk.FLAT,
                font=("Segoe UI", 10),
                padding=(10, 5)
            )
            
            # Stil dropdown
            style.configure(
                "TCombobox",
                fieldbackground=self.colors["bg_input"],
                background=self.colors["bg_input"],
                foreground=self.colors["text_primary"],
                arrowcolor=self.colors["accent"],
                borderwidth=0,
                relief=tk.FLAT
            )
            
            # Stil scrollbar
