        def scroll_to_selection(self):
            """Scrollează automat la elementul selectat"""
            if not self.menu_items:
                return
            
            # Calculează poziția elementului selectat
            item_height = 114  # 110 + 2*2 pady
            y_position = self.current_selection * item_height
            
            # Obține înălțimea canvas-ului
            canvas_height = self.canvas.winfo_height()
            
            # Calculează scroll position pentru a centra elementul
            scroll_position = y_position - (canvas_height / 2) + (item_height / 2)
            
            # Obține dimensiunea totală
            total_height = len(self.menu_items) * item_height
            
            if total_height > 0:
                # Convertește la fracțiune pentru yview_moveto
                fraction = max(0, min(1, scroll_position / total_height))
                self.canvas.yview_moveto(fraction)
                
