        def load_all_configs(self):
            self.config_data.clear()
            self.menu_items.clear()
            
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            
            # XML keys
            for tag in self.xml_keys:
                key = f"XML:{tag}"
                cursor.execute("SELECT value FROM app_flags WHERE key=?", (tag,))
                row = cursor.fetchone()
                if row is None:
                    cursor.execute("INSERT INTO app_flags (key, value) VALUES (?, 'True')", (tag,))
                    self.config_data[key] = 'True'
                else:
                    self.config_data[key] = row[0] if row[0] in ['True', 'False'] else 'True'
                self.menu_items.append(key)
            
            # INST95 keys (numele afisat e numele fisierului original)
            for filename in self.inst95_keys:
                db_key = filename.replace('.inst95', '').replace('.', '_')
                key = f"INST95:{filename}"
                
                # m95ec nu se afiseaza daca nu exista in db
                if filename == "m95ec.inst95":
                    cursor.execute("SELECT value FROM app_flags WHERE key=?", (db_key,))
                    row = cursor.fetchone()
                    if row is None:
                        continue
                    self.config_data[key] = row[0] if row[0] in ['True', 'False'] else 'True'
                    self.menu_items.append(key)
                    continue
                
                cursor.execute("SELECT value FROM app_flags WHERE key=?", (db_key,))
                row = cursor.fetchone()
                if row is None:
                    cursor.execute("INSERT INTO app_flags (key, value) VALUES (?, 'True')", (db_key,))
                    self.config_data[key] = 'True'
                else:
                    self.config_data[key] = row[0] if row[0] in ['True', 'False'] else 'True'
                self.menu_items.append(key)
            
            conn.commit()
            conn.close()
        
