            self.setup_window()
            self.setup_fonts()
            self.setup_variables()
            self.create_menu()
            self.create_toolbar()
            self.create_main_interface()
            self.create_status_bar()
            self.clear_results()
            
            # Recovery engine
            self.recovery_engine = RealFileRecoveryEngine()
            self.is_scanning = False
            
