            self.w95_text = "#000000"
            
            # Configure Windows 95 style
            self.configure_w95_style()
            
            # Clipboard history storage
            self.clipboard_history = []
            self.current_clipboard = ""
            
            # Add flag to track when we're setting clipboard content ourselves
            self.setting_clipboard = False
            self.last_clipboard_time = 0
            self.last_copied_by_us = ""  # Track what we last copied to avoid re-adding it
            
            # Autosave settings
            self.autosave_var = tk.BooleanVar(value=False)
