            # Create status bar
            self.create_status_bar()
            
            # Create clipboard history list
            self.create_clipboard_list()
            
            # Create preview area
            self.create_preview_area()
            
            # Start clipboard monitoring thread
            self.monitor_active = True
            self.monitor_thread = threading.Thread(target=self.monitor_clipboard)
            self.monitor_thread.daemon = True
            self.monitor_thread.start()
            
            # Update status initially
            self.update_status("Application started. Clipboard monitoring is active.")
            
            # Schedule first autosave check
            self.schedule_autosave()
            
            # Set up protocol for window closing
