                ("Router", "router", "#4CAF50"),
                ("Switch", "switch", "#2196F3"),
                ("Hub", "hub", "#FF9800"),
                ("Firewall", "firewall", "#F44336"),
                ("Access Point", "access_point", "#9C27B0"),
