        def create_device_button(self, parent, name, device_type, color):
            btn_frame = tk.Frame(parent, relief='raised', bd=1, bg=self.button_color)
            
            # Device icon
            icon_canvas = tk.Canvas(btn_frame, width=30, height=20, bg=color, 
                                   highlightthickness=0)
            icon_canvas.pack(pady=2)
            
            # Device name
            label = tk.Label(btn_frame, text=name, bg=self.button_color, fg=self.text_color,
                            font=('MS Sans Serif', 7))
            label.pack()
            
            def add_device():
                if self.real_mode:
                    messagebox.showinfo("Real Mode", "In real mode, devices are auto-discovered.\nSwitch to simulation mode to add virtual devices.")
                    return
                    
                x = random.randint(100, 400)
                y = random.randint(100, 300)
                device = NetworkDevice(x, y, device_type, f"{name}{len([d for d in self.devices if d.device_type == device_type and not d.is_real]) + 1}")
                self.devices.append(device)
                self.refresh_display()
                self.status_label.config(text=f"{name} added to network")
                
            btn_frame.bind("<Button-1>", lambda e: add_device())
            icon_canvas.bind("<Button-1>", lambda e: add_device())
            label.bind("<Button-1>", lambda e: add_device())
            
            return btn_frame
        
