        def create_w95_button(self, parent, text, command):
            btn_frame = tk.Frame(parent, relief='raised', bd=1, bg=self.button_color)
            btn_frame.pack(side='left', padx=1, pady=1)
            
            btn = tk.Label(btn_frame, text=text, bg=self.button_color, fg=self.text_color,
                          font=('MS Sans Serif', 8), cursor='hand2')
            btn.pack(padx=6, pady=2)
            
            def on_enter(e):
                btn_frame.configure(relief='raised', bd=1)
                
            def on_leave(e):
                btn_frame.configure(relief='raised', bd=1)
                
            def on_click(e):
                btn_frame.configure(relief='sunken', bd=1)
                self.roottopologyy.after(100, lambda: btn_frame.configure(relief='raised', bd=1))
                command()
                
            btn.bind("<Enter>", on_enter)
            btn.bind("<Leave>", on_leave)
            btn.bind("<Button-1>", on_click)
            btn_frame.bind("<Button-1>", on_click)
            
            return btn_frame
        
