        def switch_to_simulation(self):
            """Enhanced mode switching with proper cleanup"""
            self.real_mode = False
            self.mode_var.set("simulation")
            self.mode_indicator.config(bg='yellow')
            self.network_monitor.stop_monitoring()
            self.realtime_label.config(text="SIMULATION MODE", bg='yellow', fg='black')
            
            # Clear real devices when switching to simulation
            self.clear_all_real_devices()
            
            self.status_label.config(text="Switched to Simulation Mode - Virtual playground active")
            self.log_alert("Switched to Simulation Mode - Virtual playground active")
            
            # ADAUGĂ ACEASTĂ LINIE:
            self.update_real_info()  # ← FORȚEAZĂ ACTUALIZAREA IMEDIATĂ
            
            self.refresh_display()
            
        def switch_to_real_network(self):
            self.real_mode = True
            self.mode_var.set("real")
            self.mode_indicator.config(bg='lightgreen')
            self.realtime_label.config(text="REAL NETWORK MODE", bg='lightgreen', fg='black')
            self.status_label.config(text="Switched to Real Network Mode - Live monitoring active")
            self.log_alert("Switched to Real Network Mode - Live monitoring active")
            self.network_monitor.start_monitoring()
            
            # ADAUGĂ ACEASTĂ LINIE:
            self.update_real_info()  # ← FORȚEAZĂ ACTUALIZAREA IMEDIATĂ
            
            self.discover_real_network()
            
        def discover_real_network(self):
            if not self.real_mode:
                return
                
            self.status_label.config(text="Discovering real network devices...")
            self.log_alert("Starting enhanced network discovery...")
            
            # Start discovery in background thread
            def discovery_worker():
                try:
                    # Get local interfaces first
                    interfaces = psutil.net_if_addrs()
                    stats = psutil.net_if_stats()
                    local_ips = []
                    
                    self.roottopologyy.after(0, lambda: self.log_alert("Analyzing network interfaces..."))
                    
                    for interface, addrs in interfaces.items():
                        if interface in stats and stats[interface].isup:
                            interface_type = "Wi-Fi" if any(keyword in interface.lower() 
                                                          for keyword in ['wifi', 'wireless', 'wlan', 'wi-fi']) else "Ethernet"
                            
                            for addr in addrs:
                                if addr.family == socket.AF_INET and not addr.address.startswith('127.'):
                                    local_ips.append((addr.address, interface, interface_type))
                                    self.roottopologyy.after(0, lambda i=interface, t=interface_type, ip=addr.address: 
                                                   self.log_alert(f"Found {t} interface: {i} - {ip}"))
                    
                    # Add localhost first
                    self.add_real_device("127.0.0.1", "localhost", "pc")
                    
                    # Process each interface
                    for ip, interface, interface_type in local_ips[:5]:  # Limit to first 5 interfaces
                        parts = ip.split('.')
                        
                        # Try to find gateway
                        gateway_candidates = [f"{parts[0]}.{parts[1]}.{parts[2]}.1", 
                                            f"{parts[0]}.{parts[1]}.{parts[2]}.254"]
                        
                        for gateway_ip in gateway_candidates:
                            if gateway_ip != ip and self.ping_host_sync(gateway_ip, timeout=2):
                                self.add_real_device(gateway_ip, f"Gateway-{interface_type}", "router")
                                break
                        
                        # Add current device
                        hostname = f"This-{interface_type}-Device"
                        self.add_real_device(ip, hostname, "pc")
                    
                    self.roottopologyy.after(0, lambda: self.status_label.config(text="Network discovery completed"))
                    self.roottopologyy.after(0, lambda: self.log_alert("Enhanced network discovery completed"))
                    
                except Exception as e:
                    error_msg = f"Discovery error: {str(e)}"
                    self.roottopologyy.after(0, lambda: self.log_alert(error_msg))
                    self.roottopologyy.after(0, lambda: self.status_label.config(text="Discovery failed - check network connection"))
                    
            discovery_thread = threading.Thread(target=discovery_worker, daemon=True)
            discovery_thread.start()
            
        def add_real_device(self, ip, hostname, device_type):
            # Check if device already exists
            for device in self.devices:
                if device.is_real and device.ip_address == ip:
                    return device
                    
            # Create new real device
            x = random.randint(200, 600)
            y = random.randint(150, 400)
            device = NetworkDevice(x, y, device_type, hostname, is_real=True)
            device.ip_address = ip
            device.status = "online" if self.ping_host_sync(ip) else "offline"
            
            self.devices.append(device)
            self.real_devices[ip] = device
            
            self.roottopologyy.after(0, self.refresh_display)
            self.roottopologyy.after(0, lambda: self.log_alert(f"Discovered: {hostname} ({ip})"))
            
            return device
            
        def ping_host_sync(self, ip, timeout=1):
            """Synchronous ping for immediate feedback - Wi-Fi optimized"""
            try:
                if platform.system().lower() == "windows":
                    cmd = f"ping -n 1 -w {timeout*1000} {ip}"
                else:
                    cmd = f"ping -c 1 -W {timeout} {ip}"
                    
                result = subprocess.run(cmd.split(), 
                                      capture_output=True, 
                                      text=True, 
                                      timeout=timeout+2)  # Extra time for Wi-Fi
                
                return result.returncode == 0
            except subprocess.TimeoutExpired:
                return False
            except Exception as e:
                print(f"Ping error for {ip}: {e}")
                return False
        
        def refresh_real_data(self):
            if not self.real_mode:
                return
                
            self.status_label.config(text="Refreshing real network data...")
            
            def refresh_worker():
                for device in self.devices:
                    if device.is_real:
                        # Update ping status
                        device.status = "online" if self.ping_host_sync(device.ip_address) else "offline"
                        
                        # Get real ping time
                        device.real_ping_time = self.get_real_ping_time(device.ip_address)
                        
                self.roottopologyy.after(0, self.refresh_display)
                self.roottopologyy.after(0, lambda: self.status_label.config(text="Real data refreshed"))
                self.roottopologyy.after(0, lambda: self.log_alert("Real network data refreshed"))
                
            refresh_thread = threading.Thread(target=refresh_worker, daemon=True)
            refresh_thread.start()
            
        def get_real_ping_time(self, ip):
            """Get actual ping time to a host"""
            try:
                if platform.system().lower() == "windows":
                    cmd = f"ping -n 1 {ip}"
                else:
                    cmd = f"ping -c 1 {ip}"
                    
                result = subprocess.run(cmd.split(), capture_output=True, text=True, timeout=3)
                if result.returncode == 0:
                    # Extract ping time from output
                    time_pattern = r'time[<=](\d+\.?\d*)ms'
                    match = re.search(time_pattern, result.stdout)
                    if match:
                        return float(match.group(1))
            except:
                pass
            return None
        
