        def on_network_event(self, event_type, data):
            """Handle network monitoring events"""
            if event_type == 'device_discovered':
                self.add_real_device(data['ip'], data['hostname'], data['device_type'])
            elif event_type == 'interface_stats':
                self.interface_stats = data
                self.update_real_info()  # ← ASIGURĂ-TE CĂ ACEASTĂ LINIE EXISTĂ
            elif event_type == 'scan_started':
                interface = data.get('interface', 'Unknown')
                network = data.get('network', 'Unknown')
                self.roottopologyy.after(0, lambda: self.log_alert(f"Scanning {network}.x on {interface}..."))
            elif event_type == 'scan_completed':
                found = data.get('found', 0)
                network = data.get('network', 'Unknown')
                self.roottopologyy.after(0, lambda: self.log_alert(f"Scan completed on {network}.x - Found {found} devices"))
        
