        def update_real_info(self):
            """Update real network information display"""
            # ÎNLOCUIEȘTE COMPLET CONȚINUTUL CU:
            
            info_text = ""
            
            if self.real_mode:
                info_text = "Real Network Mode Active\n"
                
                # Verifică dacă există interface_stats
                if hasattr(self, 'interface_stats') and self.interface_stats:
                    info_text += "Network Interfaces:\n"
                    for interface, stats in self.interface_stats.items():
                        info_text += f"{interface}: ⬆{stats.bytes_sent//1024}KB ⬇{stats.bytes_recv//1024}KB\n"
                else:
                    info_text += "Gathering interface data...\n"
                
                # Adaugă info despre dispozitive
                real_devices = len([d for d in self.devices if d.is_real])
                info_text += f"Real devices found: {real_devices}\n"
                
                # Status monitoring
                monitoring_status = "Running" if self.network_monitor.running else "Stopped"
                info_text += f"Monitoring: {monitoring_status}\n"
            else:
                info_text = "Simulation Mode\n"
                sim_devices = len([d for d in self.devices if not d.is_real])
                info_text += f"Virtual devices: {sim_devices}\n"
                info_text += f"Connections: {len(self.connections)}\n"
            
            # ADAUGĂ enable/disable ca la log_alert:
            self.real_info_text.config(state='normal')
            self.real_info_text.delete(1.0, tk.END)
            self.real_info_text.insert(1.0, info_text)
            self.real_info_text.config(state='disabled')
        
        def log_alert(self, message):
            """Add message to alert log with timestamp"""
            timestamp = datetime.now().strftime("%H:%M:%S")
            full_message = f"[{timestamp}] {message}\n"
            
            self.alert_text.config(state='normal')
            self.alert_text.insert(tk.END, full_message)
            self.alert_text.see(tk.END)
            self.alert_text.config(state='disabled')
        
        # Real network tools
        def real_ping_test(self):
            ip = simpledialog.askstring("Real Ping Test", "Enter IP address to ping:")
            if ip:
                self.status_label.config(text=f"Pinging {ip}...")
                
                def ping_worker():
                    try:
                        ping_time = self.get_real_ping_time(ip)
                        if ping_time is not None:
                            message = f"Ping to {ip}: {ping_time}ms - SUCCESS"
                            success = True
                        else:
                            message = f"Ping to {ip}: FAILED - Host unreachable"
                            success = False
                            
                        self.roottopologyy.after(0, lambda: self.log_alert(message))
                        self.roottopologyy.after(0, lambda: messagebox.showinfo("Ping Result", message))
                        self.roottopologyy.after(0, lambda: self.status_label.config(text="Ping completed"))
                        
                    except Exception as e:
                        error_msg = f"Ping error: {str(e)}"
                        self.roottopologyy.after(0, lambda: self.log_alert(error_msg))
                        self.roottopologyy.after(0, lambda: messagebox.showerror("Ping Error", error_msg))
                        
                ping_thread = threading.Thread(target=ping_worker, daemon=True)
                ping_thread.start()
        
        def real_ping_selected(self):
            if self.selected_device and self.selected_device.is_real:
                ip = self.selected_device.ip_address
                self.status_label.config(text=f"Pinging {ip}...")
                
                def ping_worker():
                    ping_time = self.get_real_ping_time(ip)
                    if ping_time is not None:
                        self.selected_device.real_ping_time = ping_time
                        self.selected_device.status = "online"
                        message = f"Ping to {self.selected_device.name} ({ip}): {ping_time}ms"
                    else:
                        self.selected_device.status = "offline"
                        message = f"Ping to {self.selected_device.name} ({ip}): FAILED"
                        
                    self.roottopologyy.after(0, lambda: self.log_alert(message))
                    self.roottopologyy.after(0, lambda: self.refresh_display())
                    self.roottopologyy.after(0, lambda: self.status_label.config(text="Ping completed"))
                    
                ping_thread = threading.Thread(target=ping_worker, daemon=True)
                ping_thread.start()
            else:
                messagebox.showwarning("No Selection", "Please select a real network device to ping")
        
        def real_traceroute(self):
            ip = simpledialog.askstring("Real Traceroute", "Enter destination IP:")
            if ip:
                self.status_label.config(text=f"Tracing route to {ip}...")
                
                def trace_worker():
                    try:
                        if platform.system().lower() == "windows":
                            cmd = f"tracert {ip}"
                        else:
                            cmd = f"traceroute {ip}"
                            
                        result = subprocess.run(cmd.split(), capture_output=True, text=True, timeout=30)
                        
                        # Show results in a new window
                        self.roottopologyy.after(0, lambda: self.show_traceroute_results(ip, result.stdout))
                        self.roottopologyy.after(0, lambda: self.log_alert(f"Traceroute to {ip} completed"))
                        
                    except Exception as e:
                        error_msg = f"Traceroute error: {str(e)}"
                        self.roottopologyy.after(0, lambda: messagebox.showerror("Traceroute Error", error_msg))
                        
                trace_thread = threading.Thread(target=trace_worker, daemon=True)
                trace_thread.start()
        
        def show_traceroute_results(self, ip, output):
            """Show traceroute results in a new window"""
            result_window = tk.Toplevel(self.roottopologyy)
            result_window.title(f"Traceroute to {ip}")
            result_window.configure(bg=self.bg_color)
            result_window.geometry("600x400")
            
            text_frame = tk.Frame(result_window, bg=self.bg_color)
            text_frame.pack(fill='both', expand=True, padx=10, pady=10)
            
            text_widget = tk.Text(text_frame, bg='white', fg='black', font=('Courier', 9))
            scrollbar = tk.Scrollbar(text_frame, command=text_widget.yview)
            text_widget.configure(yscrollcommand=scrollbar.set)
            
            text_widget.insert(1.0, output)
            text_widget.config(state='disabled')
            
            text_widget.pack(side='left', fill='both', expand=True)
            scrollbar.pack(side='right', fill='y')
        
