        def scan_selected_ports(self):
            if self.selected_device and self.selected_device.is_real:
                ip = self.selected_device.ip_address
                device = self.selected_device  # Salvează referința local
                self.status_label.config(text=f"Scanning ports on {ip}...")
                
                def scan_worker():
                    common_ports = [21, 22, 23, 25, 53, 80, 110, 135, 139, 143, 443, 445, 993, 995, 3389, 5432, 3306, 1433, 5900, 8080, 8443, 9090]
                    open_ports = []
                    
                    self.roottopologyy.after(0, lambda: self.log_alert(f"Scanning {len(common_ports)} ports on {ip}..."))
                    
                    for port in common_ports:
                        try:
                            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                            sock.settimeout(3)
                            result = sock.connect_ex((ip, port))
                            if result == 0:
                                open_ports.append(port)
                                self.roottopologyy.after(0, lambda p=port: self.log_alert(f"✓ Port {p} is OPEN"))
                            sock.close()
                        except Exception as e:
                            self.roottopologyy.after(0, lambda p=port, err=str(e): self.log_alert(f"⚠ Error scanning port {p}: {err}"))
                            
                    # Verifică dacă device-ul încă există înainte de a seta open_ports
                    if device and hasattr(device, 'open_ports'):
                        device.open_ports = open_ports
                    
                    # Mesaj mai detaliat
                    if open_ports:
                        message = f"Port scan of {device.name if device else ip}: Found {len(open_ports)} open ports: {open_ports}"
                        result_text = f"Open ports on {ip}:\n{', '.join(map(str, open_ports))}\n\nTotal: {len(open_ports)} ports"
                    else:
                        message = f"Port scan of {device.name if device else ip}: No open ports found"
                        result_text = f"No open ports found on {ip}\n\nThis could mean:\n• Firewall is blocking\n• No services running\n• Network connectivity issues"
                    
                    self.roottopologyy.after(0, lambda: self.log_alert(message))
                    self.roottopologyy.after(0, lambda: messagebox.showinfo("Port Scan Results", result_text))
                    
                    # Verifică dacă device-ul încă există înainte de a actualiza proprietățile
                    if device and hasattr(device, 'open_ports'):
                        self.roottopologyy.after(0, lambda: self.update_properties_panel(device))
                        
                    self.roottopologyy.after(0, lambda: self.status_label.config(text=f"Port scan completed - {len(open_ports)} ports found"))
                    
                scan_thread = threading.Thread(target=scan_worker, daemon=True)
                scan_thread.start()
            else:
                messagebox.showwarning("No Selection", "Please select a real network device to scan")
        
