        def update_traffic_graph(self):
            """Fixed traffic graph update with error handling"""
            try:
                # Traffic visualization
                self.traffic_canvas.delete("all")
                
                if not self.devices:
                    # No devices to display, schedule next update and return
                    self.roottopologyy.after(2000, self.update_traffic_graph)
                    return
                    
                # Draw traffic bars for each device
                canvas_width = self.traffic_canvas.winfo_width()
                if canvas_width <= 1:
                    canvas_width = 200
                    
                bar_width = max(1, canvas_width // len(self.devices))
                
                for i, device in enumerate(self.devices):
                    x = i * bar_width
                    
                    if device.is_real and device.real_ping_time is not None:
                        # Use ping time as traffic indicator for real devices
                        height = min(80, device.real_ping_time * 2)
                        color = 'green' if device.real_ping_time < 20 else 'yellow' if device.real_ping_time < 50 else 'red'
                    else:
                        # Use simulated traffic for virtual devices
                        height = (device.traffic / 100) * 80
                        color = 'green' if device.traffic < 50 else 'yellow' if device.traffic < 80 else 'red'
                    
                    self.traffic_canvas.create_rectangle(x, 100-height, x+bar_width-1, 100,
                                                       fill=color, outline='white')
                
                # Update traffic values for simulation devices only
                for device in self.devices:
                    if not device.is_real:
                        device.traffic = max(0, min(100, device.traffic + random.randint(-10, 10)))
                
            except Exception as e:
                # Log error but don't crash the application
                print(f"Error in traffic graph update: {e}")
                self.log_alert(f"Traffic graph error: {str(e)}")
            finally:
                # Always schedule the next update
                self.roottopologyy.after(2000, self.update_traffic_graph)
        
