        def simulate_network_alerts(self):
            if random.random() < 0.05 and not self.real_mode:  # 5% chance in simulation mode
                # Get list of non-real devices and check if it's not empty
                sim_devices = [d for d in self.devices if not d.is_real]
                if sim_devices:  # Only proceed if there are simulation devices
                    device = random.choice(sim_devices)
                    alerts = [
                        f"High traffic on {device.name}",
                        f"Connection timeout to {device.name}",
                        f"Port utilization warning on {device.name}",
                        f"VLAN {device.vlan} broadcast storm detected"
                    ]
                    alert = random.choice(alerts)
                    self.log_alert(f"[SIM] {alert}")
            
            # Schedule next check
            self.roottopologyy.after(5000, self.simulate_network_alerts)
        
        # Event handlers (copy from previous implementation)
        def on_click(self, event):
            x, y = self.canvas.canvasx(event.x), self.canvas.canvasy(event.y)
            device = self.find_device_at(x / self.zoom_level, y / self.zoom_level)
            
            if self.connection_mode:
                if device:
                    if self.selected_device is None:
                        self.selected_device = device
                        device.selected = True
                        self.status_label.config(text=f"Selected {device.name}, click another device to connect")
                    elif self.selected_device != device:
                        # Create connection
                        existing = any((self.selected_device == c.dev1 and device == c.dev2) or 
                                     (self.selected_device == c.dev2 and device == c.dev1) 
                                     for c in self.connections)
                        if not existing:
                            # Check if both devices are real
                            is_real_conn = self.selected_device.is_real and device.is_real
                            
                            # Folosește setările default
                            cable_type = getattr(self, 'default_cable_type', 'ethernet')
                            speed = getattr(self, 'default_cable_speed', '100Mbps')
                            
                            conn = Connection(self.selected_device, device, cable_type, speed, is_real_conn)
                            conn.status = getattr(self, 'default_cable_status', 'active')
                            
                            self.connections.append(conn)
                            self.status_label.config(text=f"Connected {self.selected_device.name} to {device.name}")
                        self.selected_device.selected = False
                        self.selected_device = None
                        self.temp_line = None
                    self.refresh_display()
            else:
                # Clear previous selection
                if self.selected_device:
                    self.selected_device.selected = False
                
                if device:
                    self.selected_device = device
                    device.selected = True
                    self.drag_data["x"] = x
                    self.drag_data["y"] = y
                    device_mode = "Real" if device.is_real else "Simulation"
                    self.status_label.config(text=f"Selected {device.name} ({device_mode})")
                    self.update_properties_panel(device)
                else:
                    self.selected_device = None
                    self.status_label.config(text="Ready")
                    self.update_properties_panel(None)
                
                self.refresh_display()
        
        def on_right_click(self, event):
            x, y = self.canvas.canvasx(event.x), self.canvas.canvasy(event.y)
            device = self.find_device_at(x / self.zoom_level, y / self.zoom_level)
            
            if device:
                self.show_context_menu(event, device)
        
        def show_context_menu(self, event, device):
            menu = tk.Menu(self.roottopologyy, tearoff=0, bg=self.bg_color, fg=self.text_color)
            
            device_mode = "Real" if device.is_real else "Simulation"
            menu.add_command(label=f"Properties of {device.name} ({device_mode})", 
                            command=lambda: self.edit_device_properties(device))
            menu.add_separator()
            
            if device.is_real:
                menu.add_command(label="Real Ping", command=lambda: self.ping_device_real(device))
                menu.add_command(label="Port Scan", command=lambda: self.scan_device_ports(device))
                menu.add_command(label="Traceroute", command=lambda: self.trace_to_device(device))
            else:
                menu.add_command(label="Simulate Ping", command=lambda: self.ping_device(device))
                menu.add_command(label="Set Status Online", command=lambda: self.set_device_status(device, "online"))
                menu.add_command(label="Set Status Offline", command=lambda: self.set_device_status(device, "offline"))
            
            menu.add_separator()
            menu.add_command(label="Delete", command=lambda: self.delete_device(device))
            
            menu.post(event.x_root, event.y_root)
        
        def find_device_at(self, x, y):
            for device in self.devices:
                if device.distance_to(x, y) < 30:
                    return device
            return None
        
        # Copy remaining utility methods...
        def toggle_connection_mode(self):
            self.connection_mode = not self.connection_mode
            if self.connection_mode:
                self.status_label.config(text="Connection mode: Click two devices to connect")
            else:
                self.status_label.config(text="Connection mode disabled")
                self.temp_line = None
                if self.selected_device:
                    self.selected_device.selected = False
                    self.selected_device = None
                self.refresh_display()
        
