        def auto_layout(self):
            """Fixed auto-layout with proper device count checking"""
            # Simple auto-layout algorithm
            if not self.devices:
                self.status_label.config(text="No devices to layout")
                return
                
            center_x, center_y = 400, 300
            radius = 200
            angle_step = 2 * math.pi / len(self.devices)
            
            for i, device in enumerate(self.devices):
                angle = i * angle_step
                device.x = center_x + radius * math.cos(angle)
                device.y = center_y + radius * math.sin(angle)
            
            self.refresh_display()
            self.status_label.config(text=f"Auto layout applied to {len(self.devices)} devices")
        
        def zoom_in(self):
            old_zoom = self.zoom_level
            self.zoom_level = min(3.0, self.zoom_level * 1.2)
            if old_zoom != self.zoom_level:
                self.zoom_label.config(text=f"{int(self.zoom_level * 100)}%")
                self.refresh_display()
                self.status_label.config(text=f"Zoomed in to {int(self.zoom_level * 100)}%")
            else:
                self.status_label.config(text="Maximum zoom reached (300%)")
        
        def zoom_out(self):
            old_zoom = self.zoom_level
            self.zoom_level = max(0.3, self.zoom_level / 1.2)
            if old_zoom != self.zoom_level:
                self.zoom_label.config(text=f"{int(self.zoom_level * 100)}%")
                self.refresh_display()
                self.status_label.config(text=f"Zoomed out to {int(self.zoom_level * 100)}%")
            else:
                self.status_label.config(text="Minimum zoom reached (30%)")
        
        def reset_zoom(self):
            self.zoom_level = 1.0
            self.zoom_label.config(text="100%")
            self.refresh_display()
            self.status_label.config(text="Zoom reset to 100%")
        
        def edit_device_properties(self, device):
            if device.is_real:
                messagebox.showinfo("Real Device", 
                                   f"This is a real network device.\nProperties are read-only.\n\n"
                                   f"Name: {device.name}\n"
                                   f"IP: {device.ip_address}\n"
                                   f"Status: {device.status}\n"
                                   f"Last ping: {device.real_ping_time}ms" if device.real_ping_time else "")
                return
                
            # Create properties dialog for simulation devices
            dialog = tk.Toplevel(self.roottopologyy)
            dialog.title(f"Properties - {device.name}")
            dialog.configure(bg=self.bg_color)
            dialog.geometry("300x400")
            dialog.resizable(False, False)
            
            # Make dialog modal
            dialog.transient(self.roottopologyy)
            dialog.grab_set()
            
            # Properties form
            fields = {}
            
            props = [
                ("Name", device.name),
                ("IP Address", device.ip_address),
                ("Subnet Mask", device.subnet_mask),
                ("VLAN", str(device.vlan)),
                ("Ports", str(device.ports))
            ]
            
            for i, (label, value) in enumerate(props):
                tk.Label(dialog, text=f"{label}:", bg=self.bg_color, fg=self.text_color,
                        font=('MS Sans Serif', 8)).grid(row=i, column=0, sticky='w', padx=10, pady=5)
                
                entry = tk.Entry(dialog, font=('MS Sans Serif', 8))
                entry.insert(0, value)
                entry.grid(row=i, column=1, padx=10, pady=5, sticky='ew')
                fields[label.lower().replace(' ', '_')] = entry
            
            # Status dropdown
            tk.Label(dialog, text="Status:", bg=self.bg_color, fg=self.text_color,
                    font=('MS Sans Serif', 8)).grid(row=len(props), column=0, sticky='w', padx=10, pady=5)
            
            status_var = tk.StringVar(value=device.status)
            status_combo = ttk.Combobox(dialog, textvariable=status_var, 
                                       values=["online", "offline", "warning", "error"],
                                       font=('MS Sans Serif', 8))
            status_combo.grid(row=len(props), column=1, padx=10, pady=5, sticky='ew')
            
            # Buttons
            btn_frame = tk.Frame(dialog, bg=self.bg_color)
            btn_frame.grid(row=len(props)+2, column=0, columnspan=2, pady=20)
            
            def save_properties():
                device.name = fields['name'].get()
                device.ip_address = fields['ip_address'].get()
                device.subnet_mask = fields['subnet_mask'].get()
                device.vlan = int(fields['vlan'].get() or 1)
                device.ports = int(fields['ports'].get() or 1)
                device.status = status_var.get()
                
                self.refresh_display()
                self.update_properties_panel(device)
                dialog.destroy()
            
            tk.Button(btn_frame, text="OK", command=save_properties,
                     bg=self.button_color, fg=self.text_color, font=('MS Sans Serif', 8)).pack(side='left', padx=5)
            tk.Button(btn_frame, text="Cancel", command=dialog.destroy,
                     bg=self.button_color, fg=self.text_color, font=('MS Sans Serif', 8)).pack(side='left', padx=5)
            
            dialog.columnconfigure(1, weight=1)
        
