        def ping_device(self, device):
            if device.is_real:
                self.ping_device_real(device)
            else:
                # Simulate ping for virtual devices
                ping_time = random.randint(1, 100)
                messagebox.showinfo("Simulate Ping", f"Ping to {device.name} ({device.ip_address}):\nReply time: {ping_time}ms (simulated)")
        
        def ping_device_real(self, device):
            self.status_label.config(text=f"Pinging {device.ip_address}...")
            
            def ping_worker():
                ping_time = self.get_real_ping_time(device.ip_address)
                if ping_time is not None:
                    device.real_ping_time = ping_time
                    device.status = "online"
                    message = f"Real ping to {device.name} ({device.ip_address}):\nReply time: {ping_time:.1f}ms"
                else:
                    device.status = "offline"
                    message = f"Real ping to {device.name} ({device.ip_address}):\nRequest timed out"
                    
                self.roottopologyy.after(0, lambda: messagebox.showinfo("Real Ping Result", message))
                self.roottopologyy.after(0, lambda: self.log_alert(f"Ping {device.name}: {ping_time:.1f}ms" if ping_time else "FAILED"))
                self.roottopologyy.after(0, lambda: self.refresh_display())
                self.roottopologyy.after(0, lambda: self.status_label.config(text="Ping completed"))
                
            ping_thread = threading.Thread(target=ping_worker, daemon=True)
            ping_thread.start()
        
        def scan_device_ports(self, device):
            self.scan_selected_ports()  # Use existing implementation
        
        def trace_to_device(self, device):
            if device.is_real:
                # Real traceroute
                ip = device.ip_address
                self.status_label.config(text=f"Tracing route to {ip}...")
                
                def trace_worker():
                    try:
                        if platform.system().lower() == "windows":
                            cmd = f"tracert {ip}"
                        else:
                            cmd = f"traceroute {ip}"
                            
                        result = subprocess.run(cmd.split(), capture_output=True, text=True, timeout=30)
                        self.roottopologyy.after(0, lambda: self.show_traceroute_results(ip, result.stdout))
                        
                    except Exception as e:
                        error_msg = f"Traceroute error: {str(e)}"
                        self.roottopologyy.after(0, lambda: messagebox.showerror("Traceroute Error", error_msg))
                        
                trace_thread = threading.Thread(target=trace_worker, daemon=True)
                trace_thread.start()
            else:
                # Simulate traceroute
                hops = ["192.168.1.1", "10.0.0.1", device.ip_address]
                result = f"Traceroute to {device.name} ({device.ip_address}):\n\n"
                for i, hop in enumerate(hops, 1):
                    result += f"{i:2d}  {hop}  {random.randint(1, 50)}ms\n"
                messagebox.showinfo("Simulate Traceroute", result)
        
        def toggle_simulation(self):
            self.simulation_running = not self.simulation_running
            status = "started" if self.simulation_running else "stopped"
            self.status_label.config(text=f"Network simulation {status}")
        
        # Copy all remaining utility methods from previous implementation...
        def on_drag(self, event):
            if self.selected_device and not self.connection_mode:
                x, y = self.canvas.canvasx(event.x), self.canvas.canvasy(event.y)
                dx = (x - self.drag_data["x"]) / self.zoom_level
                dy = (y - self.drag_data["y"]) / self.zoom_level
                
                self.selected_device.x += dx
                self.selected_device.y += dy
                
                self.drag_data["x"] = x
                self.drag_data["y"] = y
                
                self.refresh_display()
        
        def on_motion(self, event):
            if self.connection_mode and self.selected_device:
                x, y = self.canvas.canvasx(event.x), self.canvas.canvasy(event.y)
                self.temp_line = (self.selected_device.x * self.zoom_level, 
                                 self.selected_device.y * self.zoom_level, x, y)
                self.refresh_display()
        
        def on_release(self, event):
            pass
        
        def on_double_click(self, event):
            x, y = self.canvas.canvasx(event.x), self.canvas.canvasy(event.y)
            device = self.find_device_at(x / self.zoom_level, y / self.zoom_level)
            if device:
                self.edit_device_properties(device)
        
        def on_mousewheel(self, event):
            if event.delta > 0:
                self.zoom_in()
            else:
                self.zoom_out()
        
        def delete_selected(self):
            if self.selected_device:
                self.delete_device(self.selected_device)
        
        def delete_device(self, device):
            # Remove connections
            self.connections = [conn for conn in self.connections 
                              if device not in (conn.dev1, conn.dev2)]
            # Remove device
            self.devices.remove(device)
            if device.ip_address in self.real_devices:
                del self.real_devices[device.ip_address]
            if self.selected_device == device:
                self.selected_device = None
                self.update_properties_panel(None)
            self.refresh_display()
            self.status_label.config(text=f"{device.name} deleted")
        
        def set_device_status(self, device, status):
            device.status = status
            self.refresh_display()
            self.status_label.config(text=f"{device.name} status set to {status}")
        
        def create_connection_with_defaults(self, dev1, dev2):
            """Creează o conexiune nouă cu setările default"""
            cable_type = getattr(self, 'default_cable_type', 'ethernet')
            speed = getattr(self, 'default_cable_speed', '100Mbps')
            status = getattr(self, 'default_cable_status', 'active')
            
            # Detectează automat dacă e conexiune reală
            is_real_conn = dev1.is_real and dev2.is_real
            
            conn = Connection(dev1, dev2, cable_type, speed, is_real_conn)
            conn.status = status
            
            # Adaugă proprietăți avansate dacă sunt setate
            if hasattr(self, 'default_duplex'):
                conn.duplex = self.default_duplex
            if hasattr(self, 'default_auto_negotiate'):
                conn.auto_negotiate = self.default_auto_negotiate
            
            return conn
        
