                self.default_cable_speed = speed_var.get()
                self.default_cable_status = status_var.get()
                self.default_duplex = duplex_var.get()
                self.default_auto_negotiate = auto_negotiate_var.get()
                
                # Aplică la conexiunile existente dacă e bifat
                if apply_existing_var.get():
                    updated_count = 0
                    for conn in self.connections:
                        if not conn.is_real:  # Doar pentru conexiuni simulate
                            conn.cable_type = self.default_cable_type
                            conn.speed = self.default_cable_speed
                            conn.status = self.default_cable_status
                            updated_count += 1
                    
                    if updated_count > 0:
                        self.refresh_display()
                        self.log_alert(f"Updated {updated_count} existing connections")
                
                # Mesaj de confirmare
                cable_names = {
                    "ethernet": "Ethernet",
                    "fiber": "Fiber Optic", 
                    "wireless": "Wireless",
                    "serial": "Serial"
                }
                
