            # self.status_label.config(text=f"Selected all {len(self.devices)} devices")
        def select_all(self):
            """Fixed select all with proper device count checking"""
            if not self.devices:
                self.status_label.config(text="No devices to select")
                return
                
            for device in self.devices:
                device.selected = True
            self.refresh_display()
            self.status_label.config(text=f"Selected all {len(self.devices)} devices")
            
        def clear_all_real_devices(self):
            """Helper method to clear real devices when switching modes"""
            # Remove all real devices and their connections
            real_devices_to_remove = [d for d in self.devices if d.is_real]
            
            for device in real_devices_to_remove:
                # Remove connections involving this device
                self.connections = [conn for conn in self.connections 
                                  if device not in (conn.dev1, conn.dev2)]
                # Remove device
                self.devices.remove(device)
                
            # Clear real device tracking
            self.real_devices.clear()
            
            if real_devices_to_remove:
                self.refresh_display()
                self.log_alert(f"Removed {len(real_devices_to_remove)} real devices when switching to simulation mode")
        
