        def browse_file(self):
            file_path = filedialog.askopenfilename(
                title="Select a file to convert",
                filetypes=[
                    ("Excel files", "*.xlsx"),
                    ("CSV files", "*.csv"),
                    ("Word files", "*.docx"),
                    ("Text files", "*.txt"),
                    ("All files", "*.*")
                ]
            )
            
            if file_path:
                self.selected_file = file_path
                file_name = os.path.basename(file_path)
                self.file_label.config(text=file_name)
        
        def convert_txt_to_pdf(self, input_file, output_file):
            """Convert text file to PDF"""
            try:
                # Read text file with multiple encoding attempts
                encodings = ['utf-8', 'latin-1', 'cp1252', 'iso-8859-1']
                content = None
                
                for encoding in encodings:
                    try:
                        with open(input_file, 'r', encoding=encoding) as f:
                            content = f.read()
                        break
                    except UnicodeDecodeError:
                        continue
                
                if content is None:
                    raise Exception("Could not read file with any supported encoding")
                
                pdf = SimpleDocTemplate(output_file, pagesize=letter)
                elements = []
                styles = getSampleStyleSheet()
                
                # Split by lines and create paragraphs
                lines = content.split('\n')
                
                for line in lines:
                    line = line.strip()
                    if line:
                        # Escape special XML characters
                        line = line.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
                        p = Paragraph(line, styles['Normal'])
                        elements.append(p)
                        elements.append(Spacer(1, 6))
                    else:
                        # Empty line - add spacing
                        elements.append(Spacer(1, 12))
                
                if not elements:
                    p = Paragraph("Empty text file.", styles['Normal'])
                    elements.append(p)
                
                pdf.build(elements)
                
            except Exception as e:
                raise Exception(f"Could not convert text file.\n\nDetails: {str(e)}")
            
