                ("Remove Head", self.dll_remove_head),
                ("Remove Tail", self.dll_remove_tail),
                ("Remove At Position", self.dll_remove_at),
                ("Get At Position", self.dll_get_at),
                ("Get From Tail", self.dll_get_tail),
                ("Search", self.dll_search),
                ("Count Nodes", self.dll_count),
