            tk.Button(props_frame, text="Blur", command=lambda: self.apply_effect("blur"), **effect_btn_style).pack(pady=2)
            tk.Button(props_frame, text="Grayscale", command=self.convert_grayscale, **effect_btn_style).pack(pady=2)
