            # except ImportError:
                # raise urllib.error.URLError(
                    # "NTLM requires: pip install requests requests-ntlm")
            # auth = self.auth_config
            # extra = auth.get("extra", {}) or {}
            # user_str = auth["username"]
            # domain = extra.get("ntlm_domain", "")
            # if domain:
                # user_str = f"{domain}\\{user_str}"
            # try:
                # resp = _rq.request(method, url, headers=headers, data=data,
                                    # auth=HttpNtlmAuth(user_str, auth["password"]),
                                    # timeout=timeout, allow_redirects=False)
                # if resp.status_code >= 400:
                    # raise urllib.error.HTTPError(
                        # url, resp.status_code, resp.reason,
                        # resp.headers, io.BytesIO(resp.content))
                # return resp.status_code, resp.content, dict(resp.headers)
