        def _save_settings(self):
            try:
                conn = sqlite3.connect(self._settings_path)
                cur = conn.cursor()
                cur.execute("CREATE TABLE IF NOT EXISTS sql_studio "
                            "(key TEXT PRIMARY KEY, value TEXT)")
                pairs = {
                    'max_display_rows': str(self.max_display_rows),
                    'limit_rows_enabled': '1' if self.limit_rows_enabled.get() else '0',
                    'bold_text': '1' if self.bold_text_enabled.get() else '0',
                    'autocomplete': '1' if self.autocomplete_enabled.get() else '0',
                    'tab_border_var': self.tab_border_var,
                    'tab_border_color': self.tab_border_color,
                    'show_indicator': '1' if self.show_indicator_var.get() else '0',
                    'indicator_position': self.indicator_position_var.get(),
                    'show_txn': '1' if self.show_txn_var.get() else '0',
                    'display_mode': self.display_mode,
                    'last_db': self.current_db_path or '',
                    'query_history': json.dumps(self.query_history[-50:]),
                }
                for k, v in pairs.items():
                    cur.execute("INSERT OR REPLACE INTO sql_studio (key, value) VALUES (?, ?)", (k, v))
                conn.commit()
                conn.close()
            except Exception:
                pass
