            self.tab_border_var = "top"
            self.tab_border_menu.entryconfig(0, label="  Full Border")
            self.tab_border_menu.entryconfig(1, label="✓ Top Only")
            if self.active_tab_id and self.active_tab_id in self.query_tabs:
                tab = self.query_tabs[self.active_tab_id]
                tab.frame.configure(highlightbackground=self.tab_border_color, highlightthickness=0)
