        def _set_border_color(self, color):
            self.tab_border_color = color
            self.border_color_menu.entryconfig(0, label="✓ Purple #9b59b6" if color == '#9b59b6' else "  Purple #9b59b6")
            self.border_color_menu.entryconfig(1, label="✓ Violet #715fe4" if color == '#715fe4' else "  Violet #715fe4")
            if self.active_tab_id and self.active_tab_id in self.query_tabs:
                tab = self.query_tabs[self.active_tab_id]
                tab.frame.configure(highlightbackground=color)
                if self.tab_border_var == "top":
                    tab.top_border.configure(bg=color)
            self._save_settings()
        
