        def _toggle_display_mode(self):
            self._pager = None
            self._hide_pager_controls()
            if self.display_mode == "original":
                self.display_mode = "new"
                self.display_menu_ref.entryconfig(self.display_menu_index, label="Display Mode: Safe")
            else:
                self.display_mode = "original"
                self.display_menu_ref.entryconfig(self.display_menu_index, label="Display Mode: Classic")
            
            if self.last_results and self.last_columns:
                self._display_results(self.last_columns, self.last_results)
            self._save_settings()
        
