        def _detect_editable_table(self, query):
            """Dacă ultimul SELECT vine dintr-un singur tabel cu PK simplu,
            activează editarea inline a celulelor."""
            self._edit_table = None
            self._edit_pk = None
            try:
                stmts = [s for s in self._split_statements(query) if s.strip()]
                if not stmts:
                    return
                last = stmts[-1].strip()
                if re.search(r'\bJOIN\b', last, re.IGNORECASE):
                    return
                m = re.match(r'^SELECT\b.*?\bFROM\s+["\']?(\w+)["\']?',
                             last, re.IGNORECASE | re.DOTALL)
                if not m:
                    return
                table = m.group(1)
                real = next((t for t in self.tables_cache
                             if t.lower() == table.lower()), None)
                if not real:
                    return
                cur = self.connection.cursor()
                cur.execute(f"PRAGMA table_info('{real}')")
                pks = [c[1] for c in cur.fetchall() if c[5] == 1]
                if len(pks) == 1:
                    self._edit_table = real
                    self._edit_pk = pks[0]
            except Exception:
                pass
        
        def _split_statements(self, query):
            """Split SQL into statements, respecting string literals"""
            statements = []
            current = ""
            in_string = False
            string_char = None
            
            i = 0
            while i < len(query):
                char = query[i]
                
                if char in ("'", '"') and (i == 0 or query[i-1] != '\\'):
                    if not in_string:
                        in_string = True
                        string_char = char
                    elif char == string_char:
                        in_string = False
                        string_char = None
                
                if char == ';' and not in_string:
                    if current.strip():
                        statements.append(current.strip())
                    current = ""
                else:
                    current += char
                
                i += 1
            
            if current.strip():
                statements.append(current.strip())
            
            return statements
            
        def _stop_query(self):
            if getattr(self, '_exec_running', False) and self.connection:
                self._stop_requested = True
                try:
                    self.connection.interrupt()
                except Exception:
                    pass
                self.status_text.set("Stop requested...")
            else:
                self.status_text.set("No query running.")
            
        def _explain_query(self):
            if not self.connection:
                return 'break'
            
            query = self.query_text.get('1.0', tk.END).strip()
            if not query:
                return 'break'
            
            try:
                cursor = self.connection.cursor()
                cursor.execute(f"EXPLAIN QUERY PLAN {query}")
                plan = cursor.fetchall()
                
                self.plan_text.config(state=tk.NORMAL)
                self.plan_text.delete('1.0', tk.END)
                self.plan_text.insert('1.0', "QUERY PLAN\n" + "="*50 + "\n\n")
                
                for row in plan:
                    indent = "  " * row[1] if len(row) > 1 else ""
                    detail = row[-1] if row else ""
                    self.plan_text.insert(tk.END, f"{indent}{detail}\n")
                
                self.plan_text.config(state=tk.DISABLED)
                self._switch_to_plan()
                
            except Exception as e:
                self._add_message(f"Error: {e}", 'error')
            
            return 'break'
        
