    # Windows 95 Color Scheme
    WIN95_BG = "#c0c0c0"
    WIN95_FG = "#000000"
    WIN95_BUTTON_FACE = "#c0c0c0"
    WIN95_BUTTON_SHADOW = "#808080"
    WIN95_BUTTON_HIGHLIGHT = "#ffffff"
    WIN95_ACTIVE_TITLE = "#000080"
    WIN95_INACTIVE_TITLE = "#808080"
