        def init_database(self):
            """Initialize the database with necessary tables"""
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            
            # # Create folders table
            # cursor.execute('''
                # CREATE TABLE IF NOT EXISTS folders (
                    # id INTEGER PRIMARY KEY AUTOINCREMENT,
                    # name TEXT NOT NULL,
                    # parent_id INTEGER,
                    # created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                # )
            # ''')
            
            # # Create files table with base64 encoded content (no mime_type)
            # cursor.execute('''
                # CREATE TABLE IF NOT EXISTS files (
                    # id INTEGER PRIMARY KEY AUTOINCREMENT,
                    # name TEXT NOT NULL,
                    # folder_id INTEGER,
                    # content BLOB NOT NULL,
                    # size INTEGER,
                    # created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    # FOREIGN KEY (folder_id) REFERENCES folders (id)
                # )
            # ''')
            # Create folders table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS personal_storage_folders (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    parent_id INTEGER,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            ''')
            
            # Create files table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS personal_storage_files (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    folder_id INTEGER,
                    content BLOB NOT NULL,
                    size INTEGER,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (folder_id) REFERENCES personal_storage_folders (id)
                )
            ''')
            
            conn.commit()
            conn.close()
        
        def get_file_type(self, filename):
            """Determine file type based on extension"""
            ext = os.path.splitext(filename)[1].lower()
            
            image_ext = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.ico', '.webp', '.tiff']
            pdf_ext = ['.pdf']
            word_ext = ['.doc', '.docx']
            excel_ext = ['.xls', '.xlsx']
            ppt_ext = ['.ppt', '.pptx']
            text_ext = ['.txt', '.py', '.js', '.html', '.css', '.json', '.xml', '.java',
                       '.c', '.cpp', '.h', '.sh', '.bat', '.sql', '.php', '.rb', '.log',
                       '.ini', '.cfg', '.yaml', '.yml', '.toml', '.md', '.rst', '.csv', '.tsv']
            
            if ext in image_ext:
                return 'image'
            elif ext in pdf_ext:
                return 'pdf'
            elif ext in word_ext:
                return 'word'
            elif ext in excel_ext:
                return 'excel'
            elif ext in ppt_ext:
                return 'powerpoint'
            elif ext in text_ext:
                return 'text'
            else:
                return 'unknown'
        
