        def search_dialog(self):
            """Open search dialog"""
            search_term = simpledialog.askstring("Search", "Enter search term:")
            if not search_term:
                return
            
            self.show_search_results(search_term)
        
        def show_search_results(self, search_term):
            """Show search results in a dialog"""
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            
            # Search folders
            cursor.execute('SELECT id, name, parent_id FROM personal_storage_folders WHERE name LIKE ?',
                          (f'%{search_term}%',))
            folders = cursor.fetchall()
            
            # Search files
            cursor.execute('SELECT id, name, folder_id FROM personal_storage_files WHERE name LIKE ?',
                          (f'%{search_term}%',))
            files = cursor.fetchall()
            
            conn.close()
            
            if not folders and not files:
                messagebox.showinfo("Search", "No results found")
                return
            
            # Create results dialog
            results_win = tk.Toplevel(self.rootprsdr)
            results_win.title(f"Search Results for '{search_term}'")
            results_win.geometry("500x400")
            results_win.configure(bg="#c0c0c0")
            results_win.transient(self.rootprsdr)
            
            tk.Label(results_win, text=f"Found {len(folders) + len(files)} result(s)",
                    bg="#c0c0c0", font=("MS Sans Serif", 9)).pack(pady=10)
            
            # Listbox frame
            list_frame = tk.Frame(results_win, relief=tk.SUNKEN, bd=2)
            list_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
            
            scrollbar = tk.Scrollbar(list_frame)
            scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
            
            listbox = tk.Listbox(list_frame, font=("MS Sans Serif", 9),
                                yscrollcommand=scrollbar.set)
            listbox.pack(fill=tk.BOTH, expand=True)
            scrollbar.config(command=listbox.yview)
            
            # Store results data
            results = []
            
            # Add folders to listbox
            for folder_id, name, parent_id in folders:
                path = self.get_folder_path(folder_id)
                listbox.insert(tk.END, f"[Folder] {name} - {path}")
                results.append({'type': 'folder', 'id': folder_id, 'parent_id': parent_id})
            
            # Add files to listbox
            for file_id, name, folder_id in files:
                path = self.get_folder_path(folder_id) if folder_id else "Personal Storage"
                listbox.insert(tk.END, f"[File] {name} - {path}")
                results.append({'type': 'file', 'id': file_id, 'folder_id': folder_id})
            
            # Button frame
            btn_frame = tk.Frame(results_win, bg="#c0c0c0")
            btn_frame.pack(fill=tk.X, pady=10)
            
            def go_to_selected():
                selection = listbox.curselection()
                if not selection:
                    messagebox.showwarning("Warning", "Please select an item")
                    return
                
                item = results[selection[0]]
                if item['type'] == 'folder':
                    self.load_folder(item['parent_id'])
                else:  # file
                    self.load_folder(item['folder_id'])
                results_win.destroy()
            
            tk.Button(btn_frame, text="Go to", width=12, command=go_to_selected,
                     bg="#c0c0c0", relief=tk.RAISED, bd=2).pack(side=tk.LEFT, padx=20)
            tk.Button(btn_frame, text="Close", width=12, command=results_win.destroy,
                     bg="#c0c0c0", relief=tk.RAISED, bd=2).pack(side=tk.RIGHT, padx=20)
            
            # Double-click to go to
            listbox.bind('<Double-Button-1>', lambda e: go_to_selected())
        
        def get_folder_path(self, folder_id):
            """Get full path of a folder"""
            if folder_id is None:
                return "Personal Storage"
            
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            
            path_parts = []
            current_id = folder_id
            
            while current_id is not None:
                cursor.execute('SELECT name, parent_id FROM personal_storage_folders WHERE id = ?', (current_id,))
                result = cursor.fetchone()
                if result:
                    path_parts.insert(0, result[0])
                    current_id = result[1]
                else:
                    break
            
            conn.close()
            return "Personal Storage\\" + "\\".join(path_parts)
        
        def create_icons(self):
            """Create folder and file icons"""
            self.folder_icon_large = self.create_folder_icon(32)
            self.folder_icon_small = self.create_folder_icon(16)
            
            self.file_icon_large = self.create_file_icon(32)
            self.file_icon_small = self.create_file_icon(16)
            
            self.image_icon_large = self.create_image_icon(32)
            self.image_icon_small = self.create_image_icon(16)
            
            self.pdf_icon_large = self.create_pdf_icon(32)
            self.pdf_icon_small = self.create_pdf_icon(16)
            
            self.word_icon_large = self.create_word_icon(32)
            self.word_icon_small = self.create_word_icon(16)
            
            self.excel_icon_large = self.create_excel_icon(32)
            self.excel_icon_small = self.create_excel_icon(16)
            
            self.ppt_icon_large = self.create_ppt_icon(32)
            self.ppt_icon_small = self.create_ppt_icon(16)
            
            self.text_icon_large = self.create_text_icon(32)
            self.text_icon_small = self.create_text_icon(16)
        
        def create_folder_icon(self, size):
            """Create folder icon"""
            img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
            draw = ImageDraw.Draw(img)
            s = size / 32.0
            
            # Folder tab
            draw.polygon([(2*s, 10*s), (2*s, 6*s), (12*s, 6*s), (14*s, 8*s), (30*s, 8*s), (30*s, 10*s)],
                        fill=(255, 200, 0), outline=(128, 100, 0))
            
            # Main folder body
            draw.polygon([(2*s, 10*s), (2*s, 28*s), (30*s, 28*s), (30*s, 10*s)],
                        fill=(255, 220, 0), outline=(128, 100, 0))
            
            draw.line([(3*s, 11*s), (3*s, 27*s)], fill=(255, 255, 150), width=max(1, int(s)))
            draw.line([(3*s, 11*s), (29*s, 11*s)], fill=(255, 255, 150), width=max(1, int(s)))
            
            return ImageTk.PhotoImage(img)
        
        def create_file_icon(self, size):
            """Create generic file icon"""
            img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
            draw = ImageDraw.Draw(img)
            s = size / 32.0
            
            draw.polygon([(6*s, 2*s), (6*s, 30*s), (26*s, 30*s), (26*s, 8*s), (20*s, 2*s)],
                        fill=(255, 255, 255), outline=(0, 0, 0))
            draw.polygon([(20*s, 2*s), (20*s, 8*s), (26*s, 8*s)],
                        fill=(220, 220, 220), outline=(0, 0, 0))
            
            for i in range(3):
                y = (14 + i * 4) * s
                draw.line([(10*s, y), (22*s, y)], fill=(150, 150, 150), width=1)
            
            return ImageTk.PhotoImage(img)
        
        def create_image_icon(self, size):
            """Create image file icon"""
            img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
            draw = ImageDraw.Draw(img)
            s = size / 32.0
            
            draw.rectangle([(4*s, 4*s), (28*s, 28*s)], fill=(255, 255, 255), outline=(0, 0, 0))
            draw.rectangle([(6*s, 6*s), (26*s, 26*s)], fill=(135, 206, 235))
            draw.ellipse([(18*s, 8*s), (24*s, 14*s)], fill=(255, 255, 0))
            draw.polygon([(6*s, 26*s), (12*s, 16*s), (18*s, 26*s)], fill=(34, 139, 34))
            draw.polygon([(14*s, 26*s), (20*s, 14*s), (26*s, 26*s)], fill=(0, 100, 0))
            
            return ImageTk.PhotoImage(img)
        
        def create_pdf_icon(self, size):
            """Create PDF file icon"""
            img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
            draw = ImageDraw.Draw(img)
            s = size / 32.0
            
            draw.rectangle([(6*s, 2*s), (26*s, 30*s)], fill=(255, 255, 255), outline=(0, 0, 0))
            draw.rectangle([(6*s, 10*s), (26*s, 18*s)], fill=(200, 0, 0))
            
            return ImageTk.PhotoImage(img)
        
        def create_word_icon(self, size):
            """Create Word file icon"""
            img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
            draw = ImageDraw.Draw(img)
            s = size / 32.0
            
            draw.rectangle([(6*s, 2*s), (26*s, 30*s)], fill=(255, 255, 255), outline=(0, 0, 0))
            draw.rectangle([(6*s, 10*s), (26*s, 18*s)], fill=(41, 84, 163))
            
            return ImageTk.PhotoImage(img)
        
        def create_excel_icon(self, size):
            """Create Excel file icon"""
            img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
            draw = ImageDraw.Draw(img)
            s = size / 32.0
            
            draw.rectangle([(6*s, 2*s), (26*s, 30*s)], fill=(255, 255, 255), outline=(0, 0, 0))
            draw.rectangle([(6*s, 10*s), (26*s, 18*s)], fill=(33, 115, 70))
            
            return ImageTk.PhotoImage(img)
        
        def create_ppt_icon(self, size):
            """Create PowerPoint file icon"""
            img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
            draw = ImageDraw.Draw(img)
            s = size / 32.0
            
            draw.rectangle([(6*s, 2*s), (26*s, 30*s)], fill=(255, 255, 255), outline=(0, 0, 0))
            draw.rectangle([(6*s, 10*s), (26*s, 18*s)], fill=(208, 69, 37))
            
            return ImageTk.PhotoImage(img)
        
        def create_text_icon(self, size):
            """Create text/code file icon"""
            img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
            draw = ImageDraw.Draw(img)
            s = size / 32.0
            
            draw.rectangle([(6*s, 2*s), (26*s, 30*s)], fill=(255, 255, 255), outline=(0, 0, 0))
            draw.rectangle([(6*s, 10*s), (26*s, 18*s)], fill=(100, 50, 150))
            
            draw.line([(10*s, 20*s), (20*s, 20*s)], fill=(150, 150, 150), width=1)
            draw.line([(10*s, 24*s), (18*s, 24*s)], fill=(150, 150, 150), width=1)
            
            return ImageTk.PhotoImage(img)
        
        def get_file_icon(self, filename, size='large'):
            """Get appropriate icon based on file extension"""
            file_type = self.get_file_type(filename)
            
            if file_type == 'image':
                return self.image_icon_large if size == 'large' else self.image_icon_small
            elif file_type == 'pdf':
                return self.pdf_icon_large if size == 'large' else self.pdf_icon_small
            elif file_type == 'word':
                return self.word_icon_large if size == 'large' else self.word_icon_small
            elif file_type == 'excel':
                return self.excel_icon_large if size == 'large' else self.excel_icon_small
            elif file_type == 'powerpoint':
                return self.ppt_icon_large if size == 'large' else self.ppt_icon_small
            elif file_type == 'text':
                return self.text_icon_large if size == 'large' else self.text_icon_small
            else:
                return self.file_icon_large if size == 'large' else self.file_icon_small
        
        def load_folder(self, folder_id):
            """Load contents of a folder"""
            self.current_folder_id = folder_id
            self.canvas.delete("all")
            self.canvas_items = []
            self.selected_item = None
            
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            
            cursor.execute('SELECT id, name FROM personal_storage_folders WHERE parent_id IS ? ORDER BY name',
                          (folder_id,))
            folders = cursor.fetchall()
            
            cursor.execute('SELECT id, name, size FROM personal_storage_files WHERE folder_id IS ? ORDER BY name',
                          (folder_id,))
            files = cursor.fetchall()
            
            conn.close()
            
            self.update_address_bar()
            
            if self.view_mode == "large":
                self.draw_large_icons(folders, files)
            elif self.view_mode == "small":
                self.draw_small_icons(folders, files)
            elif self.view_mode == "list":
                self.draw_list_view(folders, files)
            else:
                self.draw_details_view(folders, files)
            
            self.status_bar.config(text=f"{len(folders)} folder(s), {len(files)} file(s)")
            self.canvas.config(scrollregion=self.canvas.bbox("all"))
        
        def draw_large_icons(self, folders, files):
            """Draw items in large icon view"""
            x, y = 10, 10
            col_width = 80
            row_height = 80
            max_cols = 8
            col = 0
            
            for folder_id, name in folders:
                if col >= max_cols:
                    col = 0
                    y += row_height
                
                item_x = x + col * col_width
                
                icon_id = self.canvas.create_image(item_x + 25, y + 20,
                                                  image=self.folder_icon_large)
                text_id = self.canvas.create_text(item_x + 25, y + 55,
                                                 text=self.truncate_name(name, 12),
                                                 font=("MS Sans Serif", 8), width=70)
                
                self.canvas_items.append({
                    'type': 'folder', 'id': folder_id, 'name': name,
                    'canvas_ids': [icon_id, text_id],
                    'bounds': (item_x, y, item_x + col_width, y + row_height)
                })
                
                for cid in [icon_id, text_id]:
                    self.canvas.tag_bind(cid, '<Button-1>',
                        lambda e, item=self.canvas_items[-1]: self.on_item_click(e, item))
                
                col += 1
            
            if folders and col > 0:
                y += row_height
                col = 0
            
            for file_id, name, size in files:
                if col >= max_cols:
                    col = 0
                    y += row_height
                
                item_x = x + col * col_width
                
                file_icon = self.get_file_icon(name, 'large')
                icon_id = self.canvas.create_image(item_x + 25, y + 20, image=file_icon)
                text_id = self.canvas.create_text(item_x + 25, y + 55,
                                                 text=self.truncate_name(name, 12),
                                                 font=("MS Sans Serif", 8), width=70)
                
                self.canvas_items.append({
                    'type': 'file', 'id': file_id, 'name': name, 'size': size,
                    'canvas_ids': [icon_id, text_id],
                    'bounds': (item_x, y, item_x + col_width, y + row_height)
                })
                
                for cid in [icon_id, text_id]:
                    self.canvas.tag_bind(cid, '<Button-1>',
                        lambda e, item=self.canvas_items[-1]: self.on_item_click(e, item))
                
                col += 1
        
