        def draw_details_view(self, folders, files):
            """Draw items in details view"""
            x, y = 10, 30
            row_height = 20
            
            self.canvas.create_text(x + 20, 15, text="Name",
                                   font=("MS Sans Serif", 8, "bold"), anchor=tk.W)
            self.canvas.create_text(x + 300, 15, text="Size",
                                   font=("MS Sans Serif", 8, "bold"), anchor=tk.W)
