        def preview_excel_file(self, name, file_content):
            """Preview Excel files with sheet tabs"""
            preview_win = tk.Toplevel(self.rootprsdr)
            preview_win.title(name)
            preview_win.geometry("750x500")
            preview_win.configure(bg="#c0c0c0")
            
            try:
                wb = openpyxl.load_workbook(io.BytesIO(file_content))
                sheet_names = wb.sheetnames
                
                tabs_frame = tk.Frame(preview_win, bg="#c0c0c0")
                tabs_frame.pack(fill=tk.X, padx=5, pady=2)
                
                content_frame = tk.Frame(preview_win, relief=tk.SUNKEN, bd=2, bg="white")
                content_frame.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)
                
                tab_buttons = []
                
                v_scroll = tk.Scrollbar(content_frame)
                v_scroll.pack(side=tk.RIGHT, fill=tk.Y)
                
                h_scroll = tk.Scrollbar(content_frame, orient=tk.HORIZONTAL)
                h_scroll.pack(side=tk.BOTTOM, fill=tk.X)
                
                text_widget = tk.Text(content_frame, wrap=tk.NONE, font=("Courier", 9),
                                     yscrollcommand=v_scroll.set, xscrollcommand=h_scroll.set, bg="white")
                text_widget.pack(fill=tk.BOTH, expand=True)
                
                v_scroll.config(command=text_widget.yview)
                h_scroll.config(command=text_widget.xview)
                
                def show_sheet(sheet_index):
                    for i, btn in enumerate(tab_buttons):
                        if i == sheet_index:
                            btn.config(relief=tk.SUNKEN, bg="white")
                        else:
                            btn.config(relief=tk.RAISED, bg="#c0c0c0")
                    
                    sheet = wb.worksheets[sheet_index]
                    
                    text_widget.config(state=tk.NORMAL)
                    text_widget.delete('1.0', tk.END)
                    
                    rows_data = []
                    max_cols = 0
                    for row in sheet.iter_rows(max_row=100, values_only=True):
                        row_values = [str(cell) if cell is not None else "" for cell in row]
                        rows_data.append(row_values)
                        max_cols = max(max_cols, len(row_values))
                    
                    col_widths = [10] * max_cols
                    for row in rows_data:
                        for i, cell in enumerate(row):
                            if i < max_cols:
                                col_widths[i] = max(col_widths[i], min(len(str(cell)), 20))
                    
                    for row in rows_data:
                        line = ""
                        for i, cell in enumerate(row):
                            if i < max_cols:
                                cell_str = str(cell)[:20]
                                line += cell_str.ljust(col_widths[i] + 2)
                        text_widget.insert(tk.END, line + "\n")
                    
                    text_widget.config(state=tk.DISABLED)
                
                for i, sheet_name in enumerate(sheet_names):
                    btn = tk.Button(tabs_frame, text=sheet_name[:15],
                                   command=lambda idx=i: show_sheet(idx),
                                   bg="#c0c0c0", relief=tk.RAISED, bd=2,
                                   font=("MS Sans Serif", 8))
                    btn.pack(side=tk.LEFT, padx=1)
                    tab_buttons.append(btn)
                
                show_sheet(0)
                wb.close()
                
            except Exception as e:
                tk.Label(preview_win, text=f"Error loading Excel file:\n{str(e)}",
                        bg="white", font=("MS Sans Serif", 9)).pack(expand=True)
            
            btn_frame = tk.Frame(preview_win, bg="#c0c0c0")
            btn_frame.pack(fill=tk.X, padx=5, pady=5)
            
            tk.Button(btn_frame, text="Save As...", width=15, relief=tk.RAISED, bd=2,
                     command=lambda: self.save_file(name, file_content), bg="#c0c0c0").pack(side=tk.LEFT, padx=5)
            tk.Button(btn_frame, text="Close", width=15, relief=tk.RAISED, bd=2,
                     command=preview_win.destroy, bg="#c0c0c0").pack(side=tk.RIGHT, padx=5)
        
        def preview_pdf_file(self, name, file_content, size):
            """Preview PDF files"""
            preview_win = tk.Toplevel(self.rootprsdr)
            preview_win.title(name)
            preview_win.geometry("700x550")
            preview_win.configure(bg="#c0c0c0")
            
            info_frame = tk.Frame(preview_win, bg="#c0c0c0")
            info_frame.pack(fill=tk.X, padx=5, pady=5)
            
            preview_frame = tk.Frame(preview_win, relief=tk.SUNKEN, bd=2, bg="white")
            preview_frame.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)
            
            canvas = tk.Canvas(preview_frame, bg="white")
            canvas.pack(fill=tk.BOTH, expand=True)
            
            pages = []
            current_page = [0]
            
            try:
                pdf_document = fitz.open(stream=file_content, filetype="pdf")
                
                for page_num in range(len(pdf_document)):
                    page = pdf_document[page_num]
                    pix = page.get_pixmap(matrix=fitz.Matrix(1.5, 1.5))
                    img_data = pix.tobytes("ppm")
                    image = Image.open(io.BytesIO(img_data))
                    
                    max_size = (650, 450)
                    image.thumbnail(max_size, Image.Resampling.LANCZOS)
                    
                    photo = ImageTk.PhotoImage(image)
                    pages.append(photo)
                
                pdf_document.close()
                
                page_label = tk.Label(info_frame, text=f"Page 1 of {len(pages)}",
                                     bg="#c0c0c0", font=("MS Sans Serif", 8))
                
                def show_page(page_num):
                    canvas.delete("all")
                    canvas.create_image(325, 225, image=pages[page_num])
                    canvas.image = pages[page_num]
                    page_label.config(text=f"Page {page_num + 1} of {len(pages)}")
                    current_page[0] = page_num
                
                def prev_page():
                    if current_page[0] > 0:
                        show_page(current_page[0] - 1)
                
                def next_page():
                    if current_page[0] < len(pages) - 1:
                        show_page(current_page[0] + 1)
                
                show_page(0)
                
                if len(pages) > 1:
                    tk.Button(info_frame, text="< Prev", command=prev_page,
                             width=8, bg="#c0c0c0").pack(side=tk.LEFT, padx=5)
                    page_label.pack(side=tk.LEFT, padx=10)
                    tk.Button(info_frame, text="Next >", command=next_page,
                             width=8, bg="#c0c0c0").pack(side=tk.LEFT, padx=5)
                
            except Exception as e:
                tk.Label(preview_frame, text=f"Error loading PDF:\n{str(e)}",
                        bg="white", font=("MS Sans Serif", 9)).pack(expand=True)
            
            btn_frame = tk.Frame(preview_win, bg="#c0c0c0")
            btn_frame.pack(fill=tk.X, padx=5, pady=5)
            
            tk.Button(btn_frame, text="Save As...", width=15, relief=tk.RAISED, bd=2,
                     command=lambda: self.save_file(name, file_content), bg="#c0c0c0").pack(side=tk.LEFT, padx=5)
            tk.Button(btn_frame, text="Close", width=15, relief=tk.RAISED, bd=2,
                     command=preview_win.destroy, bg="#c0c0c0").pack(side=tk.RIGHT, padx=5)
        
