    class DatabaseManager:
        """Manages SQLite database operations"""
        
        def __init__(self, db_path="Config/dbo_bitpack.db"):
        #def __init__(self, db_path="activity_monitor.db"):
            self.db_path = db_path
            self.init_database()
            
        def init_database(self):
            """Initialize database tables"""
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            
            # Processes table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_processes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    action TEXT NOT NULL,
                    process_name TEXT NOT NULL,
                    pid INTEGER NOT NULL,
                    cpu_percent REAL,
                    memory_mb REAL
                )
            ''')
            
            # Files table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_files (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    action TEXT NOT NULL,
                    file_path TEXT NOT NULL,
                    process_name TEXT,
                    pid INTEGER,
                    file_size INTEGER
                )
            ''')
            
            # Network table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_network (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    local_port INTEGER,
                    remote_ip TEXT,
                    remote_port INTEGER,
                    status TEXT,
                    process_name TEXT
                )
            ''')
            
            # Screenshots table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_screenshots (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    file_path TEXT NOT NULL,
                    active_processes TEXT
                )
            ''')
            
            # Clipboard table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_clipboard (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    content TEXT NOT NULL,
                    content_type TEXT,
                    hash TEXT UNIQUE
                )
            ''')
            
            # USB devices table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_usb_devices (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    action TEXT NOT NULL,
                    device_name TEXT,
                    mount_point TEXT,
                    total_size INTEGER,
                    used_size INTEGER
                )
            ''')
            
            # Sessions table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_sessions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    start_time TEXT NOT NULL,
                    end_time TEXT,
                    duration_seconds INTEGER,
                    idle_time_seconds INTEGER,
                    status TEXT
                )
            ''')
            
            # Alerts table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_alerts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    alert_type TEXT NOT NULL,
                    severity TEXT NOT NULL,
                    message TEXT NOT NULL,
                    details TEXT
                )
            ''')
            
            # System resources table - NUME SCHIMBAT
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS activity_system_resources (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    cpu_percent REAL,
                    memory_percent REAL,
                    disk_read_mb REAL,
                    disk_write_mb REAL,
                    network_sent_mb REAL,
                    network_recv_mb REAL
                )
            ''')
            
            conn.commit()
            conn.close()
        
        def insert_process(self, timestamp, action, process_name, pid, cpu_percent=0, memory_mb=0):
            """Insert process event"""
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            cursor.execute('''
                INSERT INTO activity_processes (timestamp, action, process_name, pid, cpu_percent, memory_mb)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (timestamp, action, process_name, pid, cpu_percent, memory_mb))
            conn.commit()
            conn.close()
        
