            self.roothexed.geometry("1200x700")
            
            # Windows 95 color scheme
            self.bg_color = "#c0c0c0"
            self.text_bg = "#ffffff"
            self.text_fg = "#000000"
            self.select_bg = "#000080"
            self.select_fg = "#ffffff"
            self.button_bg = "#c0c0c0"
            self.menu_bg = "#c0c0c0"
            
            self.roothexed.configure(bg=self.bg_color)
            
            self.file_path = None
            self.file_data = bytearray()
