    def save_settings(settings: dict) -> None:
        try:
            conn = sqlite3.connect(DB_PATH)
            cur = conn.cursor()
            cur.execute(
                "UPDATE planogram_studio_settings SET geometry = ?, last_dir = ? WHERE id = 1",
                (settings.get("geometry"), settings.get("last_dir")))
            conn.commit()
            conn.close()
        except Exception:  # noqa: BLE001
            pass
