        def _build_ui(self) -> None:
            # status bar first (bottom)
            status_frame = tk.Frame(self.rootplanogram95, bg=W95_BG, relief=tk.SUNKEN, bd=2)
            status_frame.pack(side=tk.BOTTOM, fill=tk.X)
